            InstancedPiecesDrawLate = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "InstancedPiecesDrawLate", false /* 1.2.402: OFF until its live flip on the DN leg */, "Baked building pieces drawn by EBM's instanced path are drawn just after the terrain and rocks instead of before them, so the parts of them hidden behind hills and rocks are not shaded for nothing. Uses copies of the materials (the game's own are not changed); same look. Applies at once. Default off.");
