            IndirectShadowPlaceholders = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectShadowPlaceholders", true,
                "With IndirectCascadeShadows on: one empty shadow draw a frame (and one per shadowed point / spot light) so Unity never skips a shadow pass that only EBM's baked casters fill. Off = as 1.2.210.");
            IndirectShadowSizeCut = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectShadowSizeCut", 2f, new ConfigDescription(   // 1.2.209: default ON (2 texels, FAP's value; Fire: perf default on)
                "With IndirectCascadeShadows on: a baked caster smaller than this many texels of a sun cascade's shadow map is not drawn into that cascade (it would be a speck). 0 = off.",
                new AcceptableValueRange<float>(0f, 8f)));
            // 1.2.213 ([seasons], Tools\DESIGN_EbmGrass_20261108.md): vanilla grass drawn by EBM on the GPU (A/B key; default off until the look check by Fire)
            IndirectGrass = EbmConfigMove.Bind(Config, "22 - Performance - Grass, Stands And Signs", "IndirectGrass", true /* 1.2.264 default (Fire 11-10 12:00 PM: perf keys go on and get tested; his hand test checks the look) */,
                "Grass is drawn by EBM on the graphics card: the blades of each patch are kept in GPU memory, the fade and view test of the game run on the GPU, and each kind of grass is one draw (the same grass). Off = the game draws grass, one draw per patch.");
            IndirectGrassUploadMs = EbmConfigMove.Bind(Config, "22 - Performance - Grass, Stands And Signs", "IndirectGrassUploadMs", 0.5f, new ConfigDescription(
                "With IndirectGrass on: milliseconds a frame for sending new or changed grass patches to the GPU (the rest wait a frame).", new AcceptableValueRange<float>(0.1f, 4f)));
            // [seasons] 11-09 (DROP_NOTES_seasons_grass2.md): E12/E13 carry, E15 cost levers
            IndirectGrassFadeCarry = EbmConfigMove.Bind(Config, "22 - Performance - Grass, Stands And Signs", "IndirectGrassFadeCarry", true,
                "With IndirectGrass on: grass that is rebuilt where you can see it (snow trails, terrain edits) carries on from what was drawn instead of fading in again, and never goes blank for a frame. Off = every rebuilt patch fades in from nothing, as the game does.");
            IndirectGrassStepGate = EbmConfigMove.Bind(Config, "22 - Performance - Grass, Stands And Signs", "IndirectGrassStepGate", true,
                "With IndirectGrass on: a footstep in deep snow (or any paint-only ground change) that cannot change any grass does not rebuild the grass around it. Grass still disappears at once where a trail really clears it. Off = every step rebuilds, as the game does.");
            IndirectGrassStepGateVerify = EbmConfigMove.Bind(Config, "90 - Debugging", "IndirectGrassStepGateVerify", false,
                "Testing aid: the step gate skips nothing; instead the grass it would have skipped is rebuilt and compared blade for blade (Debug census line: 'differed' must stay 0).");
            IndirectGrassArrayRecycle = EbmConfigMove.Bind(Config, "22 - Performance - Grass, Stands And Signs", "IndirectGrassArrayRecycle", true /* 1.2.264 Fire 11-10: on to test */,
                "With IndirectGrass on: grass patches whose blades are already on the graphics card give their 64 KB lists to a small pool (8 MB at most, trims itself) that new patches reuse, so walking makes less garbage. Turning EBM grass off afterwards rebuilds all grass once.");
            GrassPatchSize = EbmConfigMove.Bind(Config, "22 - Performance - Grass, Stands And Signs", "GrassPatchSize", 16f /* 1.2.264 Fire 11-10: on to test */, new ConfigDescription(
                "0 = the game's 8 m. Bigger grass patches mean fewer patches to build and draw; the blade count per patch is raised so the density stays. Visible: blades sit in different places, very dense kinds can thin out (1023 blades per patch at most), each snow step or terrain edit rebuilds a bigger patch, and the distance fade moves in coarser steps. Rebuilds all grass once when changed.",
                new AcceptableValueRange<float>(0f, 32f)));
            GrassFarSwayStop = EbmConfigMove.Bind(Config, "22 - Performance - Grass, Stands And Signs", "GrassFarSwayStop", 40f /* 1.2.264 Fire 11-10: on to test */, new ConfigDescription(
                "0 = off. With IndirectGrass on: grass further than this many metres stops swaying in the wind (eases out over the last 4 m). Visible: distant grass stands still. Saves graphics-card work only.",
                new AcceptableValueRange<float>(0f, 200f)));
            IndirectCoverage = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCoverage", true,
                "With IndirectRenderer on: LIVE trees, rocks, bushes and pickables in loaded zones (the ones EBM does not bake) are drawn through the same GPU-driven batches; the objects stay real, only their renderers are hidden while covered ([ghost]). Off = they draw as vanilla.");
            IndirectCoverageDisableRenderers = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCoverageDisableRenderers", true /* 1.2.211: ON (O trend: covered-but-enabled 21k -> 79k as main 15 -> 26 ms) */, "1.2.210: with IndirectCoverage, the renderers EBM covers are switched off (enabled = false), which takes them out of Unity's per-frame culling walk, instead of only hidden (forceRenderingOff, still culled every frame). Anything that turns a covered renderer back on hands that object back to vanilla. Off until the A/B proves it.");
            IndirectSparseUpload = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectSparseUpload", true, "1.2.210: the GPU instance buffers get only the slots that changed (runs split at gaps), never the whole span between the lowest and highest change (a piece built in a reused low slot could send tens of MB in one frame). Read live.");
            IndirectStableLayout = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectStableLayout", true, "1.2.210: each batch keeps its own visible range; one that outgrows it moves alone (only its draws re-bind) and a new batch takes a free row, instead of a full relayout that re-binds every draw and re-records every shadow command buffer. Read live (a flip relayouts once).");
            IndirectCasterCpuCull = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCasterCpuCull", true, "1.2.210: with IndirectCascadeShadows, each sun cascade and each point / spot light records only the batches whose zone cells can reach it (CPU cell cull, same frame, so nothing pops), in material order, and re-records only when it gains a batch or a quarter of its list went stale. Off = every batch into every caster buffer (1.2.209). Read live.");
            IndirectVertexDebug = EbmConfigMove.Bind(Config, "90 - Debugging", "IndirectVertexDebug", false, "1.2.243, a test tool: EBM's piece and rock shaders paint a bad vertex a solid colour. Orange index, red input, magenta matrix, yellow world position, white clip, cyan w. Leave off to play.");
            IndirectCascadeEmptySkip = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCascadeEmptySkip", true /* 1.2.263 default (lead 11-10 bisect: the tuned set; one line per key, revert alone) */, "1.2.242: a sun cascade stops recording a batch that drew nothing for 2 s, standing still. It returns as soon as the GPU counts an instance for it, or the camera moves. On by default since 1.2.263: less work per frame.");
            IndirectCellsJob = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCellsJob", true /* 1.2.264 Fire 11-10: on to test */, "1.2.241: the CPU cell cull (with IndirectFusedCells) walks the cells on Unity's worker threads, the game thread waiting and helping. Same answer; it helps while moving and loading, when the cull cannot reuse last frame. Off until measured.");
            IndirectSettledWalk = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectSettledWalk", true /* 1.2.263 default (lead 11-10 bisect: the tuned set; one line per key, revert alone) */, "Baked groups are walked only when something changed (a zone loads or unloads, a piece changes, snow or rain state changes), instead of every group every frame. Same draws. On by default since 1.2.263: less work per frame.");
            IndirectCameraEmptySkip = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCameraEmptySkip", true /* 1.2.263 default (lead 11-10 bisect: the tuned set; one line per key, revert alone) */, "While standing still, the camera stops submitting a batch the GPU has drawn nothing of for 2 s. It returns when the GPU counts an instance for it, or when the camera moves or a piece changes. On by default since 1.2.263: less work per frame.");
            IndirectDrawParamsCache = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectDrawParamsCache", true /* 1.2.263 default (lead 11-10 bisect: the tuned set; one line per key, revert alone) */, "1.2.241: each indirect batch keeps its draw settings between frames instead of filling them again. Same draws. On by default since 1.2.263: less work per frame.");
            IndirectFusedCells = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectFusedCells", true, "1.2.213: the CPU cell cull judges the camera, the sun volume, the sun cascades, the point / spot lights and their cube faces in ONE walk over the cells (each cell and entry tested once), instead of one walk per kind; empty cells are dropped every few seconds after a zone unloads. Same verdicts. Read live; off = as 1.2.212.");
            IndirectCachedAlive = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCachedAlive", true, "1.2.213: whether a batch's mesh / material still exists (another mod can destroy them) is asked once a frame per batch and per piece set, not again in every per-frame loop. Read live; off = as 1.2.212.");
            IndirectLocalDirtyScan = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectLocalDirtyScan", true /* 1.2.335 ON: passed its gate (town ABBA -0.42 ms with the 3 light keys, ash_dense2 -2.47 (sp19), dn_open1 ABBA -0.23 (sp20), swamp tie); Fire 11-12: "ebm settings should be on by default if they prove to work better" */, "Point and spot light shadows: a light does not re-check every baked group each frame when nothing it depends on changed since the last check (the same groups get the same shadows; only the repeated check is skipped). Off = as before.");
            IndirectLocalDirtyScanRelaxed = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectLocalDirtyScanRelaxed", true /* 1.2.335 ON: passed its gate with the other two light keys (sp19 / sp20 / town ABBA; proof 0 failed of 1,732) */, "With IndirectLocalDirtyScan on: a torch whose light flickers (moves a little every frame) still counts as unchanged while the shadow check already reused last frame's result for it, so its shadows keep their list. Off = any light movement re-checks.");
            IndirectLocalSteady = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectLocalSteady", true, "1.2.213: a point / spot light's caster buffers stay attached for a moment when the light drops out of EBM's list for a frame, and a buffer is re-recorded only when ITS list gained a batch, a quarter went stale, or one of its own batches moved (not every buffer whenever any batch got its first instance). Read live; off = as 1.2.212.");
            IndirectLightsSwept = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectLightsSwept", true /* 1.2.263 default (lead 11-10 bisect: the tuned set; one line per key, revert alone) */, "Point and spot lights are checked for shadows a slice of the list per frame, and only the ones that can cast are checked every frame. Off: every light every frame. A light gaining shadows may start up to 0.2 s later, inside its fade-in.");
            IndirectCascadeTightStride = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCascadeTightStride", true /* 1.2.263 default (lead 11-10 bisect: the tuned set; one line per key, revert alone) */, "The sun cascade caster buffers are sized to the space in use instead of the next power of two, so less is copied on the GPU each frame. Off: the old size.");
            IndirectMergedCasters = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectMergedCasters", false /* E9: off until the A/B; needs the bundle with EBM/SharedCaster (missing: today's path, one Warning) */, "Opaque baked batches that share a mesh and differ only in material cast the same shadow, so they are drawn as ONE shadow caster per sun cascade and per point / spot light instead of one per material: fewer shadow draw calls, the same shadows. Alpha-tested, wind and ripple materials keep their own caster. Off: one caster per material, as before.");
            IndirectSyncCleanup = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectSyncCleanup", true /* 1.2.264 Fire 11-10: on to test */, "A group that changed compares its instances in place and only looks up the ones that moved, and its lists are sized once. Same result with less work and less garbage while zones load. Off: the old way.");
            IndirectStagedSync = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectStagedSync", true /* 1.2.264 Fire 11-10: on to test */, "A big group joining the GPU-driven path for the first time (256+ instance slots) is prepared on a worker thread, filled at most 2 ms a frame, and switched over in one frame. Until then it draws the old instanced way, so a zone loading no longer stalls one frame. Off: registered whole on the frame it appears.");
            IndirectPointFaces = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectPointFaces", true,"1.2.210: a point light's indirect casters are recorded per cube face (six buffers, each only the batches that face can see) with the shadow caster depth bias, instead of every caster into all six faces. Read live.");
            IndirectExactCascadeSpheres = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectExactCascadeSpheres", false /* 1.2.211: OFF until Fire A/Bs the main-camera-only capture */, "1.2.224: NO EFFECT (the GPU capture was removed: its shadow-pass write corrupted piece geometry). 1.2.210 ([seasons] G5): the per-cascade caster cull uses Unity's own shadow split spheres (captured on the GPU each frame, grown by the camera's move since) instead of EBM's estimate (camera slices x 1.25 + 2 m), so fewer casters go into each cascade. Read live; off = the estimate.");
            IndirectCoverageDisablePrefabs = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCoverageDisablePrefabs", false, "1.2.210 ([ghost] step 2): with IndirectCoverage, the prefab parts coverage draws anyway are switched off once on the PREFAB, so every copy is born out of Unity's culling (no per-copy switch). A copy coverage does not draw (placement ghost, refused, baked) gets its parts switched back on at once; coverage or this key off switches every prefab part back on. Off until the A/B (none / IndirectCoverageDisableRenderers / this) proves it.");
            IndirectCoverageReach = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCoverageReach", true /* 1.2.264 Fire 11-10: on to test */, "1.2.214 ([ghost] P2): with IndirectCoverage, a covered object the camera is past the last LOD level of (where it is drawn no more) gives its GPU slots back and stays hidden, and takes them again before it can be seen (re-checked every 8 m of camera movement, by 64 m cell). Objects with no LOD end are never parked. Same picture, fewer instances to cull. Off until the A/B; live through ebm_opt.");
            IndirectCoverageLodLevels = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCoverageLodLevels", true /* 1.2.264 Fire 11-10: on to test */, "1.2.218 ([ghost] P3): with IndirectCoverageReach, a covered object holds GPU slots only for the LOD level(s) the camera is near (each level is added back before the camera can reach its distance), instead of every level at once. Same picture, fewer instances to cull. Off until the A/B; live through ebm_opt.");
            IndirectCoverageLocationProps = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCoverageLocationProps", true /* 1.2.264 Fire 11-10: on to test */, "1.2.216 ([ghost]): with IndirectCoverage, static LOCATION props (dvergr town crates, tables, beams, goblin roofs and fences, pillars, statues: network objects that are not player pieces) are drawn through the indirect batches too, when nothing can change their look (no creature, Animator, light or fire, door, container, portal, ship, cart, stand, spawner, terrain or moving body). Off until the census proves it; then default on. Live through ebm_opt.");
            FarBuildingsChangedZonesOnly = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarBuildingsChangedZonesOnly", false, "1.2.216 ([ghost]): the far-buildings digest scans a zone again only when its object count changed since its last scan (a piece placed, removed, received or unloaded), plus a safety rescan every 60 s, instead of rescanning every loaded zone round-robin (~1,400 a second in a big town). Same far buildings. Off until the A/B; live through ebm_opt.");
            IndirectGpuGrow = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectGpuGrow", true, "1.2.213: when the instance buffers grow, the old contents are copied on the GPU and only the changed slots are sent, instead of every slot again from the CPU (tens of MB in one frame at a town). Read live; needs the 1.2.213 bundle (an older bundle uses the CPU path).");
            IndirectCompactSlots = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCompactSlots", true, "1.2.213: freed instance slots are reused lowest first and the free top is trimmed, so the GPU cull runs over fewer slots after objects are handed back. Read live.");
            IndirectCellFastSkip = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCellFastSkip", true, "1.2.214: in the CPU cell walk, an entry whose batch is already marked in every view it could add to is skipped before its distance tests, and a cell wholly inside a camera view skips its entries' plane tests. Exact (the same draws). Read live.");
            SectorMirrorSlicedRebuild = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "SectorMirrorSlicedRebuild", true, "1.2.225 ([ghost]): the once-a-minute sector mirror rebuild walks the instances 8,000 a frame into staging tables and swaps them in at the end, instead of all ~135k in one frame (a ~115 ms hitch every minute in a big town). Same mirror; live through ebm_opt.");
            LodLevelCensus = EbmConfigMove.Bind(Config, "90 - Debugging", "LodLevelCensus", false, "1.2.333: with Debug logging, every 30 s a [LodCensus] line: EBM's shadow-casting baked groups and covered objects by how many LOD levels their prefab has x camera distance, plus the top single-LOD meshes by triangles (the Ashlands caster design). Off = nothing runs.");
            PhysicsCensus = EbmConfigMove.Bind(Config, "90 - Debugging", "PhysicsCensus", false, "1.2.222 ([ghost]): with Debug logging, ONE scene search of rigidbodies, ZSyncTransforms and colliders, 60 s after the local player spawns; logs the counts and the cost of that one frame. Never repeats. Off for clean perf runs.");
            IndirectIntegrityCheck = EbmConfigMove.Bind(Config, "90 - Debugging", "IndirectIntegrityCheck", false, "1.2.226 ([visual], the stretch hunt): the GPU indirect args (every 1 s) and instance matrices (8,192 slots a second, rolling) are read back and compared with what EBM uploaded; a mismatch logs an Error with the frame. Default on until the stretch is closed.");
            IndirectCascadeCounts = EbmConfigMove.Bind(Config, "90 - Debugging", "IndirectCascadeCounts", false, "1.2.244: with Debug logging, the [Cascades] line: what each sun cascade really draws, read back from the GPU twice a second.");
            FarBuildingsQuietPolling = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarBuildingsQuietPolling", true, "1.2.249: Far buildings checks its zones for changes about once a second instead of about ten times, spreads its 60 s safety rescans out, and checks for a zone hand-off four times a second instead of every frame. A changed far zone shows up to about a second later. Off: as before.");
            FarMeshReadNoRawFlags = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarMeshReadNoRawFlags", true, "Far buildings read non-readable prefab meshes from the GPU once. On: the read leaves those shared meshes' buffer targets as they are. Off: it sets the Raw flag on them first, as before (a test toggle).");
            LateJoinFromZdo = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "LateJoinFromZdo", false, "1.2.253: a piece missing from its zone's bake joins the zone's instanced group straight from its ZDO, with no object made and destroyed. Anything the ZDO cannot answer for is created as before. Off = create, join, convert as before.");
            BakeCoverageCensus = EbmConfigMove.Bind(Config, "90 - Debugging", "BakeCoverageCensus", false, "Debug census every 30 s, changes nothing: for each loaded baked zone, how many building pieces the bake draws, how many draw themselves, how many draw twice and how many draw at all nowhere (and how many of those are in view), with examples and the reason.");
            BakeVerifyCoverage = EbmConfigMove.Bind(Config, "90 - Debugging", "BakeVerifyCoverage", false, "Needs BakeCoverageCensus. A piece the census finds drawn twice, or drawn by nobody, is checked again 2 s later and, if still so, fixed the way EBM already does it (its renderers hidden or given back, a skipped piece handed back to the game). Each fix is logged. Off: counted only.");
            BakeFollowChanges = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "BakeFollowChanges", false, "A building piece the bake draws in its place is watched for changes to its saved data (paint or edits from other mods, a move), about once a second; a change the bake cannot show hands the piece back to draw itself. Off: only health and the existing hooks are followed.");
            RemoteZoneValidation = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "RemoteZoneValidation", true /* 1.2.264 Fire 11-10: on to test */, "1.2.253: a cached zone is checked against the world only when no new object has arrived for its sector for 30 s and you are within one zone; a zone with at least 25 % (and 50) of its pieces gone rebakes fresh once. Off = the quiet-time rule.");
            StreamPacerVanillaFloor = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerVanillaFloor", true /* 1.2.264 Fire 11-10: on to test */, "1.2.253: while you move, the create pacer's floor is vanilla's rate (per second, not per frame) plus a share of the frame's measured headroom. Standing still is unchanged. Off = the old floor.");
            SaveOffThread = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "SaveOffThread", true /* 1.2.264 Fire 11-10: on to test */, "1.2.253: bake cache files are written on a background thread, to a temporary file that then replaces the old one, at most once per 30 s per zone while it is active. Off = written on the main thread as before.");
            ShareAwakePropertyBlock = EbmConfigMove.Bind(Config, "23 - Performance - World Objects", "ShareAwakePropertyBlock", true /* 1.2.264 Fire 11-10: on to test */, "1.2.257: every building piece shares the one material property block the game makes for it when it loads and never uses, instead of a new one each. No visible effect. Off = one each, as the game does.");
            SaveSerializeOffThread = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "SaveSerializeOffThread", true /* 1.2.264 Fire 11-10: on to test */, "1.2.256: with SaveOffThread on, a zone's cache file is also put together on the background thread, from a copy already held, so saving makes no long frame. No visible effect. Off = put together on the main thread.");
            // 1.2.361 ([seasons] 11-13, [lead]/Fire "fix tonight"): the O town circle with 1.2.360's markers ((rig path)) put the worst EBM
            // stall frames on the bake pass's save: "frame 250: 358.3 ms; top self: EBM bake:save zone 342.4 ms" (also 149.6 and 111.1 ms). With both keys above on, the
            // file is already serialised and written off-thread; what stays on the main thread is reading every combined mesh's arrays (MeshCacheStore.ExtractBatchDataFromLive).
            SaveSliced = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "SaveSliced", false /* 1.2.368 [seasons]: default OFF, cold ABBA pair 2 not a win (hitches >50 ms ON 52 / 29 vs OFF 17 / 24, worst 155 / 104.5 vs 95.8 / 88.7 ms; 5-s low 22.4 / 22.8 vs 22.4 / 23.5); gated wins ship ON, non-wins do not */, "1.2.361: with SaveOffThread and SaveSerializeOffThread on, a freshly baked zone's cache save reads its combined meshes one batch per step over the next frames, within 'SaveSliceBudgetMs' a frame, instead of all at once in the bake frame. No visible effect: the zone draws from its bake the whole time; only the file lands a little later. Off = the whole save in one frame, as before.");
            BakeGateSliced = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "BakeGateSliced", false /* 1.2.366 [seasons]: default OFF, no win warm (ABBA x2, [wishbone] 8-leg card) or cold (pair 1: 11.52 vs 11.74 ms, 30 vs 31 hitches, 26-28 zones baked per leg); gated wins ship ON, non-wins do not */, "1.2.361 (default off since 1.2.366): the check before a zone bakes (does any piece still wait for its material variation swap?) walks at most about 1 ms of pieces a frame and remembers a zone it found clear, instead of walking every piece of the zone on every frame the zone is due. No visible effect; a large zone's bake may start a few frames later. Off = the whole walk each time, as before.");
            IndirectCullBindCache = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCullBindCache", false /* 1.2.388 [seasons] + [visual]: default OFF until its leg shows the same instances drawn (gated wins ship ON) */, "The indirect cull binds its buffers to the compute shader only when one of them changed, instead of every frame. Same picture; it only skips work. Applies live.");
            IndirectCascadeScanReuse = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCascadeScanReuse", false /* 1.2.388 [visual]: default OFF until its Mistlands leg (gated wins ship ON) */, "The shadow-cascade record skips its per-frame check of every batch while nothing it depends on changed (same camera cell verdict, no object placed or removed, no new empty-cascade sample). Same shadows; it only skips work. Applies live.");
            CascadeAppendOnGain = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "CascadeAppendOnGain", false /* 1.2.372 [visual]: default OFF until the cold-entry capture (key off / on) and a warm town ABBA prove it; gated wins ship ON */, "1.2.372: when a newly baked batch starts casting sun shadows (a zone streaming in), its draws are appended to the four cascade shadow buffers instead of all four buffers being cleared and re-recorded (one draw per caster batch per cascade, about 1.5 ms a frame while a town streams in). The buffers are still fully re-recorded when the layout, the light or the cascade count changes, when a quarter of a cascade's batches went stale, or when the appended rows exceed a quarter of the recorded ones. No visible effect: the new batch's shadow appears in the same frame either way. Off = clear and re-record on every gain, as before.");
            IndirectCameraDrawSort = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCameraDrawSort", 0 /* 1.2.376 [seasons]: default 0 until the stand leg (mode 2 vs the 1659 O stand: 668 draws / 651 SetPass / GPU 3.7 ms) and its F2 shots prove it; gated wins ship ON */, new ConfigDescription("1.2.376: the order of the baked batches' camera draws. 0 = as before (the order the batches were made, each with its own bounds). 1 = solid batches are submitted grouped by shader and material. 2 = 1, and the solid batches also share one bounds box so the engine keeps equal materials together (fewer render-state switches per frame). No visible effect: transparent batches keep their order, shadows are unchanged.", new AcceptableValueRange<int>(0, 2)));
            ZdoFirstBake = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "ZdoFirstBake", true /* 1.2.387 ([lead], Fire decides on shipping): default false -> true. Cold town entry, same launch, cache emptied per lap (town run 3, EBM 1.2.384): ON 97,188 objects created in the entry, 191 hitches > 50 ms, no second slow stretch vs OFF 134,507 / 270-307 hitches; 1.2.370 cold ABBA 9.03 vs 10.90 ms a frame. Verifier 0 EXTRA / 0 MISSING since 1.2.378. NO migration: a saved value stays as the player set it. (1.2.369: prototype, default off.) */, "A zone with no saved bake is built from its ZDOs on the first visit and attached like a saved bake, so most of its pieces are not created live, held and converted. Pieces it cannot draw that way stay live. While you are in the area the zone's full cache file is built from its ZDOs in the background, so later visits load it from the cache. It also runs with [Cache] PersistToDisk off (no file is written then). Can be switched while playing. Off = every piece of a zone with no saved bake is created first and the zone is baked from the live pieces.");
            ZdoFirstBakeBudgetMs = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "ZdoFirstBakeBudgetMs", 0f /* 1.2.373: default 2 -> 0 ([lead]; [visual] cold budget ABBA on 1.2.371, ZdoFirstBake ON both arms: budget 0 mean 9.54 ms / 18.5 hitches / worst 126.3 / 5-s low 31.0 vs budget 2 11.41 / 26 / 144.8 / 24.6; non-wins do not ship; saved values untouched) */, new ConfigDescription("1.2.371: with ZdoFirstBake on, main-thread milliseconds a frame for the ZDO scans (scaled by the performance profile; shared by all zones being scanned; at least one ZDO a frame). A zone a creation reaches before its scan lands is attached at once with what is classified so far, and the scan keeps filling it. Not sliced in the loading screen. 0 = the whole zone in one frame (1.2.370).", new AcceptableValueRange<float>(0f, 50f)));   // 1.2.371 [seasons]: a 9-12k-piece zone scanned in one frame is an estimated 40-50 ms (1.2.369 Diagnostic: about 4 us a ZDO)
            SaveSliceBudgetMs = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "SaveSliceBudgetMs", 2f, new ConfigDescription("1.2.361: main-thread milliseconds a frame for sliced cache saves (scaled by the performance profile). At least one step runs each frame, so a save always finishes; a single very large batch is one step.", new AcceptableValueRange<float>(0.5f, 20f)));
            FarHandoffCountsSkipped = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarHandoffCountsSkipped", true, "1.2.256: when a zone loads, its far copy lets go as soon as every building there is drawn, counting pieces EBM draws without creating them. Off: on a server those zones keep the far copy on top for up to 10 s.");
            IndirectCrashFallback = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCrashFallback", true, "1.2.256: if the game crashed in the graphics driver while the GPU-driven renderer was starting, the next session alone uses the older drawing path and logs a warning; the one after tries again. Your settings are not changed. A killed game does not count.");
            CacheSeparateRoleFolders = EbmConfigMove.Bind(Config, "09 - Disk Cache", "SeparateRoleFolders", true, "1.2.255: a world's saved zones are kept apart when you host it or play it alone and when you join it as a client, because what each sees can differ. Off = one folder for both.");
            CacheLowGarbage = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "CacheLowGarbage", true /* 1.2.287 Fire 11-11 (allocation capture: the zone cache check newed a HashSet per check with this off): on */, "1.2.255: cache saves and far cache file work make far less temporary memory. No visible effect; the files are byte for byte the same. Off = as before.");
            CacheRejectChangedPrefabs = EbmConfigMove.Bind(Config, "09 - Disk Cache", "RejectChangedPrefabs", true, "1.2.255: a saved zone is rebuilt once if a building model it was baked from changed (a mod or game update, a moved pivot). Off = the old model keeps drawing until ebm_rebake.");
            CacheEmptyZoneDropsCache = EbmConfigMove.Bind(Config, "09 - Disk Cache", "EmptyZoneDropsCache", true, "1.2.255: the saved bake of a fully demolished zone is removed once the zone is known to be delivered and empty. Off = it stays and can reappear.");
            CacheKeepOtherSettings = EbmConfigMove.Bind(Config, "09 - Disk Cache", "KeepOtherSettings", true, "1.2.255: saved zones baked under other settings stay on disk, unused, until that zone bakes again. Off = they are deleted at load.");
            CachePreloadSlim = EbmConfigMove.Bind(Config, "09 - Disk Cache", "PreloadSlim", false /* 1.2.389 ([seasons], [lead]): off until the census leg proves the MB; then it ships on */, "1.2.389: a saved zone is held in memory only while it is needed. Once a zone is built, its saved copy leaves memory as soon as its file holds the same bake; zones not built yet are held near you only; a zone you reach sooner than that (a teleport) is read from its file right then, so it does not rebuild. Saves RAM (the saved zones of the whole world were held before). Can be switched while playing. Off = every saved zone of the world is held, as before.");
            CacheZdoCombineIdleRelease = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "ZdoCombineIdleRelease", false /* 1.2.389 ([seasons], [lead]): off until a leg; then it ships on */, "1.2.389: the first-visit bake ([Cache] ZdoFirstBake) keeps a copy of each building model it has combined. With this on, those copies are freed after a minute without use and read again when a zone next needs them. Saves RAM; the first zone built after a quiet minute reads its models again. Can be switched while playing. Off = the copies stay until you leave the world.");
            CachePreloadNearOnly = EbmConfigMove.Bind(Config, "09 - Disk Cache", "PreloadNearOnly", false, "1.2.255: only saved zones near you are held in memory, which saves RAM. A far zone reached quickly, as by teleport, may rebuild from its live pieces that visit. Off = every saved zone of the world is loaded.");
            CacheMaxMBPerWorld = EbmConfigMove.Bind(Config, "09 - Disk Cache", "MaxMBPerWorld", 512, new ConfigDescription("1.2.255: disk space one world's saved zones may use; the least recently used are removed first. It also bounds their memory. 0 = no limit.", new AcceptableValueRange<int>(0, 16384)));
            CacheMaxMBAllWorlds = EbmConfigMove.Bind(Config, "09 - Disk Cache", "MaxMBAllWorlds", 2048, new ConfigDescription("1.2.255: disk space all worlds' saved zones may use together; the least recently visited other world is removed first. 0 = no limit.", new AcceptableValueRange<int>(0, 65536)));
            IndirectCoverAfterBakeEnds = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "CoverAfterBakeEnds", true, "1.2.255: a piece a bake gives back is drawn through the indirect batches again. Off = it stays on the slower path until reload.");
            CoverageBatchedStart = EbmConfigMove.Bind(Config, "23 - Performance - World Objects", "CoverageBatchedStart", false, "New trees, rocks and pickables are handed to the faster draw path in one pass late in the frame instead of one at a time as each appears. Visible effect: none; when very many appear at once some wait a frame longer on the normal path. Off = as before.");
            // 1.2.272 (lead 11-10 10 PM, FDT 1181: ZNetView.Awake postfix 5.91 ms/s at load). Fire's rule: new perf keys ON to test.
            CoverageRegistryAttach = EbmConfigMove.Bind(Config, "23 - Performance - World Objects", "CoverageRegistryAttach", true /* 1.2.272 Fire 11-10: on to test */, "Loading trees, rocks and pickables are only noted when they appear and handed to the faster draw path late in the frame once you can get close enough to see them, instead of each one getting an extra component the moment it loads. Shorter loading hitches; nothing changes on screen (until handed over, the game draws them itself). Off = as before.");
            CoverageRegistryVerify = EbmConfigMove.Bind(Config, "90 - Debugging", "CoverageRegistryVerify", false, "Test runs only: for the first 2,000 objects handed over, judge them again from scratch and count any that come out different from what was noted at load (Debug [CoverageRegistry] line). Changes nothing.");
            // 1.2.274 (lead 11-10): far registered objects held back stay enabled renderers Unity culls every frame; off = attach everything late (the old cover + park), on = 1.2.272 reach gate
            CoverageRegistryReachGate = EbmConfigMove.Bind(Config, "23 - Performance - World Objects", "CoverageRegistryReachGate", false, "With CoverageRegistryAttach on: hand far trees and bushes to the faster draw path only once you can get close to them. Off (default): every one is handed over within a few frames of loading, so far ones are parked out of the game's own per-frame checks as before.");
            // 1.2.273 (lead 11-10, Fire "yes to all"; FDT 1182: DG_SunkenCrypt 7,390 enabled renderers seen from outside). Fire's rule: new perf keys ON to test.
            DungeonInteriorCull = EbmConfigMove.Bind(Config, "22 - Performance - Grass, Stands And Signs", "DungeonInteriorCull", true /* 1.2.273 Fire 11-10: on to test */, "Dungeon insides (built far above their entrance) are not drawn while you are outside: their walls, lights and looping effects are switched off and come back the moment you go in, before the first frame inside is drawn. Doors, chests, enemies and loot are never touched. Less work per frame near crypts and burial chambers. Off = as before.");
            DungeonInteriorCullVerify = EbmConfigMove.Bind(Config, "90 - Debugging", "DungeonInteriorCullVerify", false, "Test runs only: when a dungeon inside is shown again, count anything that was already switched back on by something else (Warning once, Debug census). Changes nothing.");
            // 1.2.275 (lead 11-10, swamp profile: RenderDeferred.Lighting 1.30 ms): census only, changes nothing
            LightCensus = EbmConfigMove.Bind(Config, "90 - Debugging", "LightCensus", false /* 1.2.312 OFF (Fire: diagnostics never on by default; [release] audit); was true since 1.2.275; DefaultsMigrated1312 */, "Debug logging only: every 30 s, count the lights the game has on near you (type, shadows, in view, tiny on screen, who owns them). Changes nothing.");
            LightTinyCut = EbmConfigMove.Bind(Config, "21 - Performance - Lights, Fires And Sound", "LightTinyCut", true /* 1.2.275 Fire 11-10: on to test */, "Lamps and fires that are only a speck on your screen (far away) skip their shadow, and the smallest skip their light, for that frame only; anything you are near or that the game already manages by distance is never touched. Less lighting work per frame. Off = as before.");
            LightTinyShadowScreen = EbmConfigMove.Bind(Config, "21 - Performance - Lights, Fires And Sound", "LightTinyShadowScreen", 0.03f, new ConfigDescription("With LightTinyCut: a lamp's light reach smaller than this share of the screen height skips its shadow.", new AcceptableValueRange<float>(0f, 0.5f)));
            LightTinyOffScreen = EbmConfigMove.Bind(Config, "21 - Performance - Lights, Fires And Sound", "LightTinyOffScreen", 0.01f, new ConfigDescription("With LightTinyCut: a lamp's light reach smaller than this share of the screen height is skipped for that frame.", new AcceptableValueRange<float>(0f, 0.5f)));
            // 1.2.280 (lead 11-11, town -> swamp flight: the frame after a drain avg 95.9 ms, worst 692.7 ms). Fire's rule: new perf keys ON to test.
            DestroyCostCap = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "DestroyCostCap", false /* 1.2.280 on to test; 1.2.281 OFF: proven worse (flight A/B 11-11: drain 98.8 s / worst 805 ms on vs 47.8 s / 604 ms off) */, "When you leave a big area, its objects are removed only as fast as your frame can take it (EBM measures what each removal really costs), and the big batches wait for loading screens; the backlog still clears within seconds. Fewer stutters when leaving a town. Off = as before.");
            DestroyHeightmapBulkDetach = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "DestroyHeightmapBulkDetach", true /* 1.2.281 Fire 11-11: on to test */, "When many building pieces are removed at once (leaving a town), each patch of ground's list of the pieces standing on it is updated once instead of once per piece. Much shorter stutters when leaving a big base. Off = as before.");
            // 1.2.282 (Fire 11-11: "we shouldn't create far baked pieces until we're in range"; raid band x2: "yes during an active raid it could double")
            SkipFarBakedPieces = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "SkipFarBakedPieces", true /* 1.2.282 Fire 11-11: on to test */, "Plain building parts (walls, floors, roofs, beams) beyond the area the game actively simulates around every player are not created as game objects until someone comes that close; EBM draws them meanwhile and an invisible collider keeps their shape. The game does not simulate pieces out there anyway, so nothing changes in play. Doors, beds, stations, chests, fires, lights and wards are always created. Far fewer objects in big bases: faster loading and leaving. Off = as before.");
            // 1.2.286 (lead 11-11, Fire "get that done": dungeon interiors and location buildings drawn GPU-side). Fire's rule: new perf keys ON to test.
            IndirectStaticClusters = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectStaticClusters", true /* 1.2.286 Fire 11-11: on to test */, "Dungeon rooms and the fixed parts of locations (ruins, crypt walls, towers) are drawn by the faster draw path in big batches instead of thousands of separate pieces. Anything that moves, animates or is networked stays as the game draws it. Off = as before.");
            // 1.2.287 (lead 11-11 allocation capture: 37% of bytes in the WearNTear Start / OnDestroy multicast Combine / Remove; EBM's own copy for players without FiresFixes)
            PiecesGroupedPerTile = EbmConfigMove.Bind(Config, "23 - Performance - World Objects", "PiecesGroupedPerTile", true /* 1.2.287 Fire 11-11: on to test */, "Building pieces register with the ground they stand on through one shared callback per patch of ground instead of one each, so placing, loading and removing pieces stops churning memory. FiresFixes' own copy takes over when it is installed and on. Off = as before.");
            // 1.2.291 (round-2 E5, lead 11-11): the 8 pixel-light slots go to the lights that matter most on screen
            IndirectCascadeSphereScale = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCascadeSphereScale", 1.25f /* 1.2.300: the old fixed value; test 1.0 behind a gate ABBA */, new ConfigDescription(
                "With IndirectCascadeShadows on: how much larger than the camera slice each sun-shadow cascade's caster area is (1.25 = as before). Smaller = fewer shadow casters drawn, but a shadow can go missing at a cascade edge.", new AcceptableValueRange<float>(1f, 2f)));
            IndirectCascadeSphereMarginM = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCascadeSphereMarginM", 2f /* 1.2.300: the old fixed value; test 0 behind a gate ABBA */, new ConfigDescription(
                "With IndirectCascadeShadows on: metres added to each sun-shadow cascade's caster area (2 = as before).", new AcceptableValueRange<float>(0f, 20f)));
            IndirectVegetationPrepass = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectVegetationPrepass", true /* 1.2.311 ON (with NoClip): swamp -0.40 ms, town -0.17 ms, Fire look check passed (DefaultsMigrated1311) */,
                "With IndirectRenderer on: leaf and branch cards (alpha-cut, a few triangles) first write only their depth, then shade only the front layer, instead of shading every overlapping card. Same look; fewer pixels shaded where foliage is dense. Off = as before.");
            IndirectVegetationPrepassNoClip = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectVegetationPrepassNoClip", true /* 1.2.311 ON (with the prepass; DefaultsMigrated1311) */,
                "With IndirectVegetationPrepass: the cards' colour pass uses a copy of the shader without the alpha cut (the depth pass already cut the leaves), so the graphics card can skip hidden leaf pixels before shading them. Same look. Off = the colour pass keeps the alpha cut.");
            IndirectCreatureVariant = EbmConfigMove.Bind(Config, "40 - Shaders", "IndirectCreatureVariant", false, "EBM draws static trophies and items on stands (the game's Custom/Creature shader) with its own creature shader copy. Off = the game's shader (or another mod's) draws them. [wishbone] 11-11: static trophies and items on stands (Custom/Creature) get EBM's own GPU-driven variant, so coverage can take them. Rebuilt from vanilla's look (hue/saturation/value, styles, metal, two-sided normals, cutout, shadows). Materials with noise glow or Add Rain stay on Unity (not reproduced). Off until Fire checks the look. Takes effect for items covered after the switch (next load for all).");
            IndirectCreatureVariantVerify = EbmConfigMove.Bind(Config, "90 - Debugging", "IndirectCreatureVariantVerify", false, "[wishbone] 11-11: diagnostic for IndirectCreatureVariant: checks that each covered Custom/Creature renderer is drawn exactly once (Unity renderer off and one GPU instance). With Debug logging: every 5 s, any covered creature-shader item drawn other than once is a Warning (capped), plus one census line of covered / refused-by-reason. Off = no cost.");
            StandInsKeptPastCap = EbmConfigMove.Bind(Config, "30 - Fixes", "StandInsKeptPastCap", true /* 1.2.345 FIX (Fire's run_7: bridges with no collision on one zone's half) */,
                "When a zone's pieces are handed back to the game for a rebake and some are still not created 60 s later, their stand-in colliders stay until the real pieces exist (one Warning names the zone and a piece). Off = as before 1.2.345: every stand-in of the zone was dropped at 60 s and a not-yet-created piece had no collider at all (players fell through bridge decks).");
            IndirectClonesFollowSeason = EbmConfigMove.Bind(Config, "30 - Fixes", "IndirectClonesFollowSeason", true /* 1.2.342 FIX (Fire's run_4: bare trees / white rocks after a season change) */,
                "With IndirectRenderer on and a season mod (Vedr): EBM's GPU-drawn trees, bushes and rocks follow the season repaint of their materials at once (textures and colours re-copied from the game's materials on every season change). Off = as before 1.2.342: they keep the look of the season they were first drawn in.");
            ZoneLoadedIgnoresObjectLoading = EbmConfigMove.Bind(Config, "30 - Fixes", "ZoneLoadedIgnoresObjectLoading", true /* 1.2.314 FIX: the load-in pop Fire saw ([ZoneFlip] on 1.2.312) */,
                "A nearby zone stays loaded for EBM while the game is still spawning a location or dungeon inside it (the game briefly reports such a zone as not loaded). Fixes buildings and trees popping out and back in while the world first loads. Off = as before.");
            IndirectFaceRowsOnReuse = EbmConfigMove.Bind(Config, "30 - Fixes", "IndirectFaceRowsOnReuse", true /* 1.2.335 ON: passed its gate (sp19 ash_dense2 7.34 -> 4.87 ms, draws 4,232 -> 2,514; sp20 dn_open1 ABBA -0.23 ms) */, "Point-light shadows of baked pieces: on frames that reuse the last visibility check, each cube face keeps drawing only the pieces in its own view instead of every piece in the light's reach. Fewer shadow draws, the same shadows. Off = as before.");
            FarNeedsGround = EbmConfigMove.Bind(Config, "30 - Fixes", "FarNeedsGround", false /* 1.2.416 FIX, OFF until its check (Fire's gate rule) */, "Far rocks and far trees are drawn only where the ground under them is already drawn, so none hang in the sky while the far terrain is still building (on arrival, or after moving far). Off = as before.");
            ArrivalAreaFirst = EbmConfigMove.Bind(Config, "30 - Fixes", "ArrivalAreaFirst", false /* 1.2.325: OFF until its OFF->ON arrival proof (Fire's gate rule); 1.2.323 FIX for the 30 s "not 'ready'" arrivals */,
                "After a teleport, respawn or login, the objects around you are created as soon as your own zone and its neighbours are loaded, instead of waiting until every zone of the whole active area has loaded (which took 30 s and more in big towns). Off by default until it is proven; on = the fix.");
            if (!ArrivalAreaFirst.Value) EasyBakeLog.Info("[Arrival] [Fixes] ArrivalAreaFirst is off (default until its proof): arrivals wait for the whole active area as the game does. Set it to true to create the area around you first.");
            ZoneKeepWithEbmPieces = EbmConfigMove.Bind(Config, "30 - Fixes", "ZoneKeepWithEbmPieces", true /* 1.2.312 FIX (Fire: far buildings popped in / out on the first load) */,
                "Nearby zones whose buildings EBM draws are kept loaded exactly as if those buildings were normal game objects. Fixes buildings and trees popping in and out while the world first loads. Off = the game unloads them when it sees no live objects there.");
            // 1.2.513 ([lead] psnow51 zone flips): see ZoneTrackerZoneKeep.InKeepBand
            ZoneKeepBand = EbmConfigMove.Bind(Config, "30 - Fixes", "ZoneKeepBand", true /* 1.2.514: ON (passed: rig A/B 11-24 baked-zone edge flips 12 -> 0, worst shuttle frame 289 -> 173 ms; Fire "Yes you can turn it on"); a saved value is kept */,
                "Zones whose buildings EBM draws stay loaded one zone further out than the game loads them, so walking back and forth across a zone border no longer unloads and reloads the zones at the edge of the loaded area (each time: their buildings handed back and re-baked, stand-ins rebuilt, snow values re-sent). The zone unloads as soon as you are two zones past the edge. Off = as before.");
            IndirectVegetationPrepassMaxInstances = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectVegetationPrepassMaxInstances", 800, new ConfigDescription(
                "With IndirectVegetationPrepass: a card batch holding more instances than this skips the depth prepass (many tiny cards cost more to draw twice than they save). 0 = no limit.", new AcceptableValueRange<int>(0, 100000)));
            IndirectVegetationPrepassMaxTris = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectVegetationPrepassMaxTris", 64, new ConfigDescription(
                "With IndirectVegetationPrepass: the largest card mesh (triangles per submesh) that gets the depth prepass.", new AcceptableValueRange<int>(8, 4096)));
            IndirectLavaVariant = EbmConfigMove.Bind(Config, "40 - Shaders", "IndirectLavaVariant", false /* 1.2.301: OFF until the Ashlands gate */,
                "EBM draws Ashlands lava with its own lava shader copy. Off = EBM stands down; Vedr's or FiresTossinShade's lava shader, or the game's, draws it. "
                + "With IndirectRenderer on: Ashlands lava (Custom/FlowOpaque) gets EBM's own GPU-driven copy (ported from Fires TossinShade's lava), so coverage can draw it in batches; same look. Takes effect for lava covered after the switch (next load for all). Off = the game's own lava.");
            IndirectLavaVariant.SettingChanged += (_, __) => EbmApi.RecheckShaderOwnership("IndirectLavaVariant key", true);   // 1.2.318 shader priority
            IndirectRenderer.SettingChanged += (_, __) => EbmApi.RecheckShaderOwnership("IndirectRenderer key", true);   // 1.2.342: the master flip reaches the lower mods at once, not at the next 1 s check
            IndirectStandardMoreKeywords = EbmConfigMove.Bind(Config, "40 - Shaders", "IndirectStandardMoreKeywords", false /* 1.2.301: OFF until gate ABBA */,
                "With IndirectRenderer on: Standard materials with specular highlights or glossy reflections switched off (many hung items, props) are drawn by EBM's own batches too, with the same look. Takes effect for objects covered after the switch (next load for all). Off = they stay the game's own.");
            IndirectFarCardShadows = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectFarCardShadows", true /* 1.2.311 ON (Fire: proven, swamp -0.19 ms; DefaultsMigrated1311)  ([lead] town_FarCards on 1.2.298: 0.68 ms slower, cause = a re-record every frame, fixed in 1.2.299; back ON once an A/B on the fix wins) */,
                "With IndirectCascadeShadows on: small leaf and branch cards (alpha-cut, a few triangles) cast no shadow in the far sun-shadow cascades (the 3rd and 4th), where their shadow is a few texels of dappled noise. Near shadows and what you see are unchanged. Off = as before.");
            LightBudgetPixelLights = EbmConfigMove.Bind(Config, "21 - Performance - Lights, Fires And Sound", "LightBudgetPixelLights", 8 /* 1.2.297: back to 8 ([lead] s4_LightSlots on 1.2.296: 4 = 4.213 ms vs 8 = 4.045 ms, fewer slots measured SLOWER); 1.2.296 had 4 */, new ConfigDescription(
                "With the light budget on: how many torch / fire lights near you keep full lighting (and their shadows). The rest light water, sign writing and particles more simply and cast no shadow. Fewer = faster near water and in lit towns. 8 = as before 1.2.296.",
                new AcceptableValueRange<int>(1, 16)));
            LightBudgetScreenRank = EbmConfigMove.Bind(Config, "21 - Performance - Lights, Fires And Sound", "LightBudgetScreenRank", true /* 1.2.291 Fire 11-11: on to test */, "With the light budget on: of the nearby lamps and fires, the ones that light the most of what you see keep full lighting, instead of simply the closest ones. Off = closest first.");
            // 1.2.291 (round-2 E25, lead 11-11; Fire's low RAM rule): far-building mesh copies unused for 10 minutes are released, read again from the far cache when needed
            FarSourceIdleRelease = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarSourceIdleRelease", true /* 1.2.291 Fire 11-11: on to test */, "With far buildings on: the far-view copy of a building type nobody has seen for 10 minutes is dropped from memory and read again from the cache when it is needed. Less memory on long trips. Off = kept all session.");
            StaticClustersVerify = EbmConfigMove.Bind(Config, "90 - Debugging", "StaticClustersVerify", false, "Test runs only: for the first 50 dungeon rooms / location parts handed to the faster draw path, check that every part is drawn exactly once (Warning on a hole or a double draw). Changes nothing.");
            BakePassBudgetMs = EbmConfigMove.Bind(Config, "26 - Performance - Bakes And Cache", "BakePassBudgetMs", 0f, new ConfigDescription("Milliseconds the bake decision walk may spend in one frame before leaving the remaining zones for the next frame, so several zones' cache checks, bakes and saves stop landing in one frame. A single zone still finishes its step once started. Visible effect: none; a waiting zone keeps drawing its original pieces a frame or more longer. 0 = no limit, as before.", new AcceptableValueRange<float>(0f, 50f)));
            BakeFrameSplit = EbmConfigMove.Bind(Config, "90 - Debugging", "BakeFrameSplit", true, "Only while Debug logging is on: every 30 s, one line naming where the zone tracker's worst frame went (cache check, trim, teardown, bake, save read / serialise / write, orphan census, pumps) and which zone took the largest step. Measurement only, no effect on the game.");
            StreamPacerMotionFromReference = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerMotionFromReference", true, "1.2.256: the create pacer judges whether you are moving from the position the game loads the world around (your own position in normal play), measured every frame. A fix: the old test could miss motion entirely. Off = the old test from the player's position.");
            // next EBM ([lead] GO 11-22, O_20261122_080519: a player treading water at a fixed spot flipped moving / standing 93 times in ~4 min on the vertical bob alone)
            StreamPacerMotionHorizontal = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerMotionHorizontal", false, "A/B (off = today): the create pacer and the far buildings judge whether you are moving from your sideways motion only. The world loads by position on the ground, so bobbing in water, jumping or falling no longer counts as moving.");
            StreamPacerUnfocusedBoostOnlyWhenThrottled = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerUnfocusedBoostOnlyWhenThrottled", true, "1.2.256: when the game is not the focused window, the create pacer uses its larger background budget (40 ms a pass) only if the game is really slowed in the background (the frame's other work takes over twice the target frame, or it is not set to run in the background). A game still running at full speed behind another window keeps its normal budget. No visible effect while you watch the game; alt-tabbed loading is unchanged. Off = always the background budget when unfocused.");
            // 1.2.265 (lead / Fire 11-10, TESTPLAN Tier 0 row 0b: the client create cost on a dedicated server), each its own key, ON to test
            StreamPacerThroughArrival =EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerThroughArrival", true /* 1.2.265 Fire 11-10: on to test */, "During arrival (loading screen, teleport) the game creates the area around you exactly as before until the spot you arrive at is ready (so nobody falls or waits longer); from then on EBM's paced create takes the rest of the area instead of the game's full sort of every object. Off = the game creates the whole arrival area.");
            StreamPacerCompilersFirst = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerCompilersFirst", true /* 1.2.427: ON (lead's order; Fire's slow terrain swap) */, "A zone's terrain edits (its _TerrainCompiler) are created before every other object, nearest first, as soon as the zone's ground exists, even while the rest of the area is still loading. Off = the edits wait in line with everything else and for the whole area to load.");
            StreamPacerNearFirst =EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerNearFirst", true /* 1.2.265 Fire 11-10: on to test */, "Objects in your own zone and the ring around it are always created before anything further away gets time, so nothing next to you waits behind distant objects. Off = the older fair rotation, which can serve a far bucket first.");
            StreamPacerSectorLeave =EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerSectorLeave", true /* 1.2.265 Fire 11-10: on to test */, "An object that leaves its zone (moved or removed) leaves EBM's create queue at once (and rejoins if it moved somewhere near), instead of waiting for the queue to find out. Off = as before.");
            StandQuickCheck = EbmConfigMove.Bind(Config, "22 - Performance - Grass, Stands And Signs", "StandQuickCheck", true /* 1.2.265 Fire 11-10: on to test */, "Item and armour stands refresh their look every 4 s; when the shown item, variant and facing are the same as before (the game itself then changes nothing), EBM skips its own re-check of the stand too. No visible effect. Off = EBM re-checks every stand every time.");
            IndirectMeshDriftSlow = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectMeshDriftSlow", true /* 1.2.265 Fire 11-10: on to test */, "EBM's always-on check that a drawn mesh still matches what the GPU was told steps 10 times a second instead of every frame (a full lap of all batches in about 2 s instead of half a second). Same safety, less work per frame.");
            IndirectPlaceholderCachedBounds = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectPlaceholderCachedBounds", true /* 1.2.265 Fire 11-10: on to test */, "The empty shadow draw that keeps Unity from skipping a shadow pass only EBM's casters fill uses a box around EBM's casters kept for half a second, instead of rebuilding it from every batch every frame. No visible effect; at most a shadow pass Unity could have skipped is kept.");
            SnowNeedsSnowMod = EbmConfigMove.Bind(Config, "08 - Snow And Seasons", "SnowNeedsSnowMod", true /* 1.2.266 Fire 11-10: on to test */, "With no snow mod loaded, snow saved on a building by a snow mod in an earlier session is not drawn by EBM outside the Deep North (the game itself only ever saves snow there). Off = EBM shows saved snow caps on far buildings in the Mountains too.");
            DestroyArrivalDrain = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "DestroyArrivalDrain", true /* 1.2.268 Fire 11-10: on to test */, "Objects leaving your area are removed faster while the screen is covered (loading, teleport: at least 8 ms a frame), and in play at most 256 a frame, because Unity removes them after the frame and the cost lands on the next one. Off = the time budget only, as before.");
            ScanGateEventHash = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "ScanGateEventHash", true /* 1.2.268 Fire 11-10: on to test */, "The check that skips the nearby-object scan while nothing changed also counts objects entering or leaving your area (not only how many there are), so one leaving as another arrives is seen too; the safety scan then runs every 3 s instead of every second. The 5 s self-check stays. Off = counts only, as before.");
            ScanGateIgnoreInAreaMoves = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "ScanGateIgnoreInAreaMoves", true /* 1.2.492 Fire 11-22: "not allowing fish and creature movement to cause churn but be ideal" */, "Needs ScanGateEventHash. Fish, creatures, ships and dropped items moving around inside your area no longer make the game rescan every nearby object; only objects entering or leaving your area, new objects and removed ones do. Nothing is created or removed any later: the 3 s safety scan and the 5 s self-check stay. Off = every move inside your area counts, as before.");
            StreamPacerMovingCap = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerMovingCap", true /* 1.2.264 Fire 11-10: on to test */, "1.2.257: while you move, objects near you appear at least as fast as in the unmodded game, and extra ones only within a small time cap each frame (at least 1 ms, unused time saved for up to 0.2 s), so the world keeps up without long frames. While on, StreamPacerVanillaFloor is not used. Standing still and loading are unchanged. Off = as before.");
            StreamPacerViewOrder = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerViewOrder", true /* 1.2.264 Fire 11-10: on to test */, "1.2.257: objects near you appear in front of you first and behind you last, closest first; anything waiting over 10 s still gets its turn (with StreamPacerNearFirst on, once your own zone and the ring around it are done). Off = closest first in every direction, as before.");
            StreamPacerRealCostCap = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerRealCostCap", true /* 1.2.264 Fire 11-10: on to test */, "1.2.256: while you stand still, the number of objects one create pass may make is worked out from what a real create costs, not an average that includes the near-free skipped ones. Same time limit; fewer objects in one frame. Off = the old count.");
            StreamPacerMotionByPosition = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerMotionByPosition", true, "1.2.252: the create pacer also counts you as moving when your position changes (flying, carried, debug fly), not only from your physics speed, so it keeps to the moving budget instead of the long standing-still one. Off = physics speed only.");
            IndirectPiecePixelShave = EbmConfigMove.Bind(Config, "40 - Shaders", "IndirectPiecePixelShave", true /* 1.2.263 default (lead 11-10 bisect: the tuned set; one line per key, revert alone) */, "1.2.251: EBM piece shader skips texture work a piece cannot use (non-triplanar materials, no snow). Same look; on by default since 1.2.263.");
            FarSourceAsync = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarSourceAsync", true, "Far buildings read and parse their cached meshes on a worker thread instead of the main thread, and start new reads only inside the frame's far budget. Off: on the main thread, as before.");
            FarUploadSliced = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarUploadSliced", true, "A far buildings job's chunks are uploaded over several frames, inside the frame's far budget; the old look stays until the whole new one is ready. Off: all of a job's chunks in one frame.");
            FarIndexRanges = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarIndexRanges", false, "Far buildings remember where each piece sits in its merged chunk. When pieces only leave a far zone, or a zone moves from a 512 m cell to its own target, those pieces are hidden in place instead of merging and uploading the whole zone or cell again. Anything else rebuilds as before. Checks itself on the GPU and switches off for the session if that check fails. Off: every change rebuilds.");
            FarZoneGrid = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarZoneGrid", false, "Far buildings and far trees read which zones are loaded once a frame into a small grid, and answer 'is any zone here loaded' for a whole area in one step. Same answers as asking zone by zone. Off: zone by zone.");
            FarHandoffProvenDrawn = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarHandoffProvenDrawn", false, "When a zone loads, its far copy waits until every building there is really drawn, counting a piece EBM draws without creating it only once its zone's baked group is drawing. Off: such a piece counts as soon as EBM has skipped it, which can be a frame or more before its group draws.");
            FarSnowLayer = EbmConfigMove.Bind(Config, "03 - Far View", "FarSnowLayer", true /* 1.2.468 ON by Fire's order 11-19: "bakes have no use for snow layers that are meant to change constantly" */, "Far buildings draw snow as a layer: each far copy bakes only where snow can sit (the snow mod's snow class x how sheltered each piece is), and the snow mod's live amount fills it in, so storms, thaws and season changes show on far buildings without any rebuild. The game's snow cap meshes are no longer merged into far copies. Needs a snow mod that registers a far snow class (Vedr); without one nothing changes. Off: far copies merge the game's snow caps as before. Takes effect at the next far rebuild (a change rebuilds them).");
            FarSnowLayer.SettingChanged += (_, __) => EasyBake.Far.FarBuildingDraw.MarkSnowDirty();
            FarKeepHandedOff = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarKeepHandedOff", true /* 1.2.424 ([visual], lead approved; Fire 11-16 far builds pop out): ON */, "A far copy that hands over to the real buildings is hidden and kept while its zone stays near (at most half the far vertex cap), and zones at the edge of the loaded area get their far copy built ahead, hidden, so walking out of the area never leaves a gap. Off: destroyed and rebuilt when needed again.");
            FarRetireSliced = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarRetireSliced", false, "Far chunks being replaced are hidden at once and destroyed a few a frame inside the far budget, instead of all in one frame. Looks the same. Off: all at once.");
            FarUploadByteCap = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarUploadByteCap", false, "Spread far chunk uploads also stop at 8 MB a frame (at least one chunk), since the GPU copy happens on the render thread, outside the main-thread budget. Off: the time budget only.");
            FarBuildViewFirst = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarBuildViewFirst", false, "Far buildings in front of the camera are built before the ones behind it. Order only: everything is still built. Off: nearest first.");
            FarCapHysteresis = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarCapHysteresis", false, "When far buildings reach their vertex cap, a far area that was dropped comes back only once the total is under 90 % and 20 s have passed, so areas in the 90-100 % band can stay hidden that long. At most 16 areas are dropped per 10 s; past that, drawn areas are kept up to 110 % of the cap, and anything that would go past 110 % is still dropped (the 16 is not a hard limit there). Stops areas at the edge of the cap being dropped and rebuilt over and over while you move. Off: dropped and re-added the moment they fit or don't.");
            FarMergePooled = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "FarMergePooled", true /* 1.2.287 Fire 11-11 (allocation capture: the unpooled merge newed ~88 KB buffers per job): on */, "Far buildings reuse their merge buffers and chunk objects instead of making new ones for every rebuild, so far buildings make far less garbage (fewer full garbage-collection pauses). Looks the same. Off: new buffers and objects each time.");
            FarGroundProbe = EbmConfigMove.Bind(Config, "90 - Debugging", "FarGroundProbe", false, "Counts only, changes nothing: measures how much far ground could be proven hidden by the terrain's own near-hide on these settings, and logs why none is skipped.");
            WearSkipCensus = EbmConfigMove.Bind(Config, "90 - Debugging", "WearSkipCensus", false /* 1.2.492 [2ic]: off in normal play */, "Counts only, changes nothing: every 30 s (with Debug logging) one [WearSkip] line says how many building pieces skip wear-and-tear updates because they cannot be damaged, and how many run them for snow. Walks every piece once per line, so leave it off in normal play; test runs turn it on.");
            IndirectSelfGate = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectSelfGate", true /* 1.2.402: ON. Its legs (1.2.401, release): stood down = renderer off within 0.012 ms at DN / circN / bf1 (DN 3.418 -> 3.261, circN 4.364 -> 3.690, bf1 kept on at 4.556 vs 6.617 off); automatic DN -> circN -> bf1 with marks 12000 / 15500, no flapping. A saved value is not changed */, "Where very little is loaded around you (Deep North, open sea far from land) the indirect renderer costs a little more than it saves. With this on it stands down there by itself: baked buildings and covered trees and rocks go back to the normal draw path a few at a time (no hitch), and come back the same way when more is loaded again. Nothing looks different. Needs IndirectRenderer. Applies at once. On by default.");
            IndirectSelfGateForce = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectSelfGateForce", 0, new ConfigDescription("For testing IndirectSelfGate (acts only while it is on). 0 = automatic. 1 = hold the indirect renderer stood down. 2 = hold it on. Applies within 2 seconds.", new AcceptableValueRange<int>(0, 2)));
            IndirectSelfGateDownAt = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectSelfGateDownAt", 12000f /* 1.2.402: loads read on the 1.2.401 leg: circN 10,743 loses 0.67 ms on, bf1 16,586 wins 2.07 ms on */, new ConfigDescription("IndirectSelfGate stands down when the load around you is at or under this number for 10 seconds (never during a teleport). The load is printed in the log line \"[Indirect] self-gate\" (baked building parts + covered trees, rocks and objects). 0 = not set: it never stands down by itself. Default 12000.", new AcceptableValueRange<float>(0f, 1000000f)));
            IndirectSelfGateUpAt = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectSelfGateUpAt", 15500f /* 1.2.402: above DownAt, below bf1's 16,586 */, new ConfigDescription("IndirectSelfGate comes back on when the load around you is at or over this number. It must be above IndirectSelfGateDownAt (the gap keeps it from switching back and forth at the edge); if it is not, the gate never stands down by itself. 0 = not set. Default 15500.", new AcceptableValueRange<float>(0f, 1000000f)));
            IndirectSlotCompact = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectSlotCompact", true /* 1.2.393 ([lead]): ON. Its gate leg (ocean, clean A/B in one launch): frame 4.616 -> 4.443 ms with 0 orphans / 0 claimed twice / 0 index mismatch, worst frame of the pass 0.85 ms; Plains 5.011 -> 5.064 (no gain; one leg each). A saved value is not changed */, "After an area has finished loading, the indirect renderer packs its instances together so every culling pass covers only what is really there (a load leaves them spread over about twice the space). Nothing is removed: the same objects draw. Can be switched while playing. Off = they stay spread out, as before.");
            IndirectSlotTrim = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectSlotTrim", true /* 1.2.393 ([lead]): ON. Speed 0, frees memory: its A/B leg (ocean, one launch) read frame 4.399 ms compacted -> 4.407 ms compacted + trimmed, with "slot arrays trimmed: 262144 -> 131072 slots of capacity ... 18 MB of managed arrays freed" (54 MB when the capacity was 524288), no frame over the segment worst at the trim. A saved value is not changed */, "The indirect renderer's per-instance arrays are sized to what the world really uses: each world remembers the most instances it drew last time (not the largest size ever reached), and while you play the arrays shrink when less than a quarter has been in use for a minute. Saves RAM and video memory. Can be switched while playing. Off = the arrays keep the largest size they ever reached.");
            IndirectPresize = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectPresize", true, "Remember each world's largest indirect buffer sizes and use them at the next load, so the buffers do not grow repeatedly while the world fills in. Off: they grow as needed.");
            ZoneTransitionBudgetMs = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "ZoneTransitionBudgetMs", 1f, new ConfigDescription("Milliseconds a frame for handing a just-unloaded zone's pieces back (at least one piece a frame). 0 = all of a zone in the frame it unloads.", new AcceptableValueRange<float>(0f, 8f)));
            IndirectGpuMeshValidator = EbmConfigMove.Bind(Config, "90 - Debugging", "IndirectGpuMeshValidator", false, "1.2.245, a test tool: reads each drawn mesh from the GPU and checks its vertices against its bounds and its indices against its vertex count, a lap every 20 s, and tests whether Far buildings changes a mesh when it reads it. Writes [GpuValidator] and [RawProbe] log lines.");
            IndirectMeshContentCheck = EbmConfigMove.Bind(Config, "90 - Debugging", "IndirectMeshContentCheck", false, "1.2.235 ([visual], the stretch hunt): each batch mesh's GPU vertex + index data is sampled (4 KB each, one mesh every 0.25 s) and hashed; a change under EBM's draws (a mod rewriting a prefab mesh in place) logs an Error naming the mesh.");
            CoverageCensus = EbmConfigMove.Bind(Config, "90 - Debugging", "CoverageCensus", false, "1.2.227: with Debug logging, the [CoverageReach] census line every 30 s (walks every covered object: ~30 ms in a big town). Off = no walk; ebm_coverage still prints it on demand.");
#if EBM_BLACKFRAME   // 1.2.365 (Fire 11-14: commented out, re-enable to debug): 1.2.359 BlackFrameWatch
            EasyBake.EbmBlackFrameWatch.Bind(Config);   // 1.2.359 [Diagnostics] BlackFrameWatch (+EverySeconds / DarkBelow / SkyAbove): the black-world detector
#endif
            // 1.2.250: FGN's client pacer moved here, so this is THE client pacer: default ON, under a new key so an old saved "StreamPacer = false" does not leave clients with none.
            StreamPacer = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "ObjectStreamPacer", true, "Client / local host: objects are created from one event queue (your zone first, solid before loose), sized from this machine's measured frame, distant objects from what is left; ZoneFilling / ZoneSettled on EbmApi. Arrival stays vanilla. Off = vanilla's create path.");
            StreamPacerBaseMs = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerBaseMs", 3, new ConfigDescription("The least time a create pass may use, when the frame has no headroom left.", new AcceptableValueRange<int>(1, 16)));
            StreamPacerMinPerFrame = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerMinPerFrame", 100, new ConfigDescription("The create pass's object cap never drops below this.", new AcceptableValueRange<int>(10, 500)));
            StreamPacerEveryFramePass = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerEveryFramePass", true, "While objects are waiting, a create pass also runs on frames vanilla's 30 per second tick skipped, so the fill follows the frame rate. Off = the 30 Hz tick only.");
            StreamPacerExtraPasses = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerExtraPasses", true, "1.2.254: with StreamPacerEveryFramePass on, whether the extra create passes also run while you move. Off = while moving, objects are created on vanilla's 30 per second tick only; standing still and arriving are unchanged.");
            TickGroupEventDriven = EbmConfigMove.Bind(Config, "23 - Performance - World Objects", "TickGroupEventDriven", false, "1.2.254: the shelter, wet and light checks re-run when what they read changes (rain, shelter, pieces added or removed, moving), with a slow timed check for the rest. Off = each on its fixed timer, as before.");
            IndirectCellReusePerCell = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCellReusePerCell", false, "1.2.254: with IndirectCellReuse, an added object re-judges only its own cell instead of the whole cell walk; a removed one costs nothing. Needs IndirectFusedCells. Off = any change re-walks every cell.");
            StreamPacerReconcileSliced = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "StreamPacerReconcileSliced", true, "1.2.338 (the 6-7 s hitch): the create queue's 5 s self-check walks a slice of at most 2 ms per frame and resumes next frame, instead of the whole queue in one frame (~50 ms when tens of thousands of objects wait). Off = the old whole-queue walk (for an A/B only).");
            StreamPacerSelfCheck = EbmConfigMove.Bind(Config, "90 - Debugging", "StreamPacerSelfCheck", false, "Test tool: every 10 s, a Debug line comparing the create queue with the game's own near list.");
            IdleObjectAreaSkip = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "IdleObjectAreaSkip", true, "With nothing near you waiting to be created or removed and the same zone, the game's 30 per second pass over every nearby object runs 10 times a second instead. Same objects, less work in big bases. Needs ObjectStreamPacer.");
            EventDrivenObjectArea = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "EventDrivenObjectArea", false, "While you stay in one zone, new nearby objects come straight from the event queue and the full gather of nearby objects runs about once a second. Objects that leave your area go within that second. Needs IdleObjectAreaSkip. Off until the A/B (ebm_eventarea flips it for a session).");
            EventAreaFullPassSeconds = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "EventAreaFullPassSeconds", 1f, new ConfigDescription("With EventDrivenObjectArea: the longest time between two full gathers (a zone change always runs one at once).", new AcceptableValueRange<float>(0.1f, 5f)));
            DestroyMoversFirst = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "DestroyMoversFirst", true, "When objects leave your area, anything that moves itself goes in that same frame and loose items go before the floors under them, so nothing is left simulating or falling. Off = one queue in scan order.");
            RemovalIdleScanLimit = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "RemovalIdleScanLimit", true, "With nothing queued for removal and the same zone, the removal scan runs at most 10 times a second. Off = every pass.");
            TeleportCreateGate = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "TeleportCreateGate", true, "While teleporting, create passes start as soon as zones arrive, and each object waits for its own zone's ground. Off = vanilla's whole-area wait.");
            DistantPrefabScanSliced = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "DistantPrefabScanSliced", true, "1.2.339 (the 5 s pair of hitches on big worlds): the distant-prefab cache rebuild walks the world's object lists in slices of at most 1 ms per frame and resumes next frame, instead of one registered prefab's whole-world walk in one frame (~40 ms on a 2.5M-object world). Off = the old whole walk (for an A/B only).");
            DistantPrefabStreaming = EbmConfigMove.Bind(Config, "25 - Performance - Far View", "DistantPrefabStreaming", true, "Streams the prefabs other mods register with EbmApi.RegisterDistantPrefab out to their distance. Nothing runs until one registers. Off = none are streamed.");
            PieceTypeAudit = EbmConfigMove.Bind(Config, "90 - Debugging", "PieceTypeAudit", false, "Diagnostic: once a session, names build pieces not marked Solid (they load in the item tier and can lose the race with what rests on them). Off = no audit.");
            ZoneLoadDiagnostics = EbmConfigMove.Bind(Config, "90 - Debugging", "ZoneLoadDiagnostics", false, "Diagnostic: Debug lines for what each zone crossing cost and which objects keep failing to create. Adds a timer around every object created. Off = no timers.");
            IndirectCasterSizeSkip = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCasterSizeSkip", true, "1.2.233: in every shadow cascade past the first, a baked batch too small to matter from that cascade's near distance (under IndirectCasterMinScreen of the screen height) is not drawn into that cascade at all: fewer draw calls. A LOOK CHANGE at a low sun: a thin caster's far shadow is longer than the caster (check far posts / fences at sunset, on vs off). Off = every reachable batch draws in every cascade.");
            IndirectCasterMinScreen = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCasterMinScreen", 0.01f, new BepInEx.Configuration.ConfigDescription("1.2.233: with IndirectCasterSizeSkip, the smallest screen-height fraction a batch's mesh must cover from a far cascade's near distance to cast there.", new BepInEx.Configuration.AcceptableValueRange<float>(0f, 0.1f)));
            IndirectLooksChangeDriven = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectLooksChangeDriven", true, "1.2.223: a GPU-drawn group whose snow / wet / pushed-look inputs did not change skips the per-frame looks prep and looks write (the exact no-op test of both, as field compares). Off = both run every frame, as before (A/B).");
            IndirectCellReuse = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectCellReuse", true, "1.2.220: the CPU cell walk keeps last frame's answer while the camera moved under 1 m and turned under 0.05 degrees, no zone cell changed and the shadow cascades and lights stayed put (its test is widened by 2 m so the kept answer always covers what can be seen; the GPU still culls each instance exactly). Standing still the walk costs ~nothing. Read live.");
            IndirectRugVariant = EbmConfigMove.Bind(Config, "40 - Shaders", "IndirectRugVariant", true, "1.2.221 ([seasons]): rugs (Custom/Rug: straw, asksvin, fur, jute) get EBM's own GPU-driven variant, so coverage can take them; same look, no shadows (vanilla rugs cast none), drawn after the floor. On since 1.2.256 (Fire checked the look). Takes effect for rugs covered after the switch (next load for all).");
            RendererCensus = EbmConfigMove.Bind(Config, "90 - Debugging", "RendererCensus", false, "1.2.218: with Debug logging, count every vanilla renderer once per 30 s (the [Indirect] visible-of-enabled line and the [CasterCensus] line). Each count starts with a scene-wide object search that takes tens of ms at a town (the 77 ms frame every 30 s in the O runs), so it is off unless you are diagnosing.");
            DestroyDistantBandSweep = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "DestroyDistantBandSweep", true /* 1.2.402: ON ([seasons], [lead]). Travel leg 1.2.401 ((rig path), one run each way, town -> circN): old zones unloaded 9.2-11.1 s after arrival with it on against 9.3-17.0 s off (off was helped by a full walk landing early; it can be 60 s+); worst visible frame 51.0 ms on against 120.9 ms off. A saved value is not changed */, "After you travel away from a big base, its objects in the far part of the loaded area are removed on the next pass, as the game itself does, instead of up to a minute later. Frees memory and drawing work sooner after travel; the removal is spread over frames as before. Applies live. On by default. Off = as before (up to a minute).");
            DestroyLeanEarmark = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "DestroyLeanEarmark", false /* 1.2.216: OFF until the pack is checked for other near-list writers ([generator]); a self-check on every zone change refuses it when one shows */, "1.2.215: the zone-leave destroy pass stamps only EBM's keepalive ZDOs and asks each leaving candidate its live sector, instead of stamping every near and distant ZDO (~134k in a town) on each pass. Never destroys more than vanilla would. Off until the [DTS] census shows the stamping is the cost. Read live.");
            // 1.2.494 ([visual], [lead] GO 11-22, perfcircle_20261122_091000: a 50 m town circle re-created ~3400 objects a lap as it crossed 6 zone borders)
            RemoveHysteresis = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "RemoveHysteresis", false, "A/B (off = today): a still object (building pieces, plants, pickables; never creatures or anything that moves itself) that leaves your area is kept until it is two zones past it or RemoveHysteresisSeconds have passed, so walking back and forth over a zone border does not destroy and re-create the same objects. Uses a little more memory and keeps a few more objects drawn while you move; a kept object outside your area gets no updates from other players until you come back (a door or a smelter can show an old state for up to RemoveHysteresisSeconds).");
            RemoveHysteresisSeconds = EbmConfigMove.Bind(Config, "20 - Performance - Loading And Streaming", "RemoveHysteresisSeconds", 30f, new ConfigDescription("With RemoveHysteresis on: the longest a still object outside your area is kept before it is removed as usual.", new AcceptableValueRange<float>(5f, 300f)));

            IndirectMinScreenPercent = EbmConfigMove.Bind(Config, "24 - Performance - GPU Drawing", "IndirectMinScreenSize", 0.1f, new ConfigDescription(   // 1.2.209 (Fire: VPO parity): default 0.1 like VPO; key renamed so the new default reaches existing cfgs
