                "ttl expired, m_forceRebuild pending, no local player, freefly, disabled). Useful when\n" +
                "ClutterSystem.LateUpdate cost in the FiresDebugginTools overlay doesn't drop while\n" +
                "parked Ã¢â‚¬â€ the line will tell you whether the prefix is even being called, and if so,\n" +
                "what's forcing it to pass through to vanilla.");

            // â”€â”€ AN EDIT TO THE .cfg ON DISK HAS TO REACH THE RUNNING GAME â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            // BepInEx never re-reads a config file on its own, and a SettingChanged handler only fires when the
            // in-memory entry changes - through the config UI or code - never from an external edit. So every
            // SettingChanged wiring above was dead to a text edit, and only Core's watcher closes that gap.
            //
            // MEASURED, 2026-09-26: ZdoBakeVerifyEnabled was set to true in the live cfg mid-run. Eleven minutes
            // later the file still read true, nothing had re-saved over it, and 89 fresh bakes had run with the
            // feature still gated off in-process. The setting never arrived. Bound last, after every Config.Bind
            // above, so the first reload cannot race an entry that does not exist yet.
            PlayerFacingConfig.Apply(Config);   // 1.2.110: short lines, basics only without Show Advanced
            CoreLink.WatchConfig(Config);

            // â”€â”€ 1.2.263 (Fire 11-09: "a rendering mod should not have to be on the server for anything other than config enforcement") â”€â”€
            // A headless dedicated server (no graphics device: -nographics / -batchmode) draws nothing, so EBM stops here: no Harmony patches
            // (no create/destroy hooks, no transpilers, no hot-method detours), no far tier or far cache, no cache preload, no per-frame Update.
            // Tools\AUDIT_ebm_dedicated_paths_20261110.md lists what this removes. EBM has no config enforcement code today; anything added for
            // that later goes ABOVE this return. [Batching] RunOnServer (default off) keeps the old behaviour for a server owner who wants it.
            // A player-hosted world has a graphics device and is unaffected.
            if (SystemInfo.graphicsDeviceType == UnityEngine.Rendering.GraphicsDeviceType.Null && !BatchingRunOnServer.Value)
            {
                EasyBakeLog.Info($"{PluginName} v{PluginVersion}: dedicated server: EBM only enforces config (nothing is patched or drawn on a headless server; [Batching] RunOnServer = true to run it here anyway).");
                EbmApi.Inert = true;   // every EbmApi entry that does work returns its neutral value (another mod calling it on a server never throws)
                enabled = false;   // no Update / LateUpdate on the server
                EbmConfigMove.End(Config);   // 1.2.444: the server's binds end here; write the cfg once
                return;
            }

            EasyBake.MeshCacheStore.Initialize();

            // Create the Harmony instance up front so the SettingChanged
            // handler below can patch/unpatch on the fly. The instance is
            // also reused by ApplyPatches / RemovePatches so toggling
            // PluginEnabled live never requires a restart.
            _harmony = new Harmony(PluginGUID);

            // Live master-toggle. When the user flips PluginEnabled in the
            // config manager, apply or remove all our patches immediately,
            // and on the OFF path also call Reset() on every stateful
            // subsystem so any baked zones, pinned ZDOs, destroy queues,
            // cached prefab classifications, etc. are unwound cleanly.
            PluginEnabled.SettingChanged += (_, __) =>
            {
                if (PluginEnabled.Value && s_disablingSince >= 0f)
                {
                    // 1.2.351: switched back on before the graceful disable finished: nothing was removed, carry on
                    s_disablingSince = -1f;
                    EasyBakeLog.Info($"{PluginName} re-enabled via config before the disable finished: patches were never removed, nothing to restore.");
                }
                else if (PluginEnabled.Value && !_patchesApplied)
                {
                    ApplyPatches();
                    EasyBakeLog.Info($"{PluginName} re-enabled via config Ã¢â‚¬â€ patches restored.");
                }
                else if (!PluginEnabled.Value && _patchesApplied && EasyBake.ZoneTracker.SkippedTotal(out int dzones) is int dpieces && dpieces > 0)
                {
                    // 1.2.351 ([wishbone]'s read of the player report "disabling EBM mid-base broke half a base", [lead] approved): the master switch used to
                    // UnpatchSelf FIRST (the HaveSupport hold went with it) and then ZoneTracker.Reset -> ReleaseSkipped: Created = false + DestroyStandIns in
                    // the SAME frame, with the tick off, so live neighbours (glass, beds, fire pits) had no ground until vanilla re-created the real pieces
                    // seconds later and broke on their owner's UpdateWear. Now the switch hands every skipped piece back first and enters a DISABLING state:
                    // patches, FinishHandBacks and the support holds keep ticking, nothing new is baked or skipped (BatchingActive is false), and the patches
                    // are removed only when every hand-back landed and the holds expired, or at the 60 s cap (the keep-colliders-past-cap rule still applies
                    // until the final Reset). Two Info lines: enter + finish.
                    s_disablingSince = Time.unscaledTime;
                    EasyBake.ZoneTracker.HandBackAllSkipped();
                    EasyBakeLog.Info($"{PluginName} disabling via config: {dpieces} skipped piece(s) in {dzones} zone(s) are handed back to the game first; patches stay until every real piece exists and the support holds expire (60 s cap); nothing new is baked or skipped meanwhile.");
                }
                else if (!PluginEnabled.Value && _patchesApplied)
                {
                    RemovePatches();
                    EasyBakeLog.Info($"{PluginName} disabled via config Ã¢â‚¬â€ patches removed, subsystem state reset.");
                }
            };

            EasyBakeLog.Debug($"[Keepalive] ZoneKeepaliveEnabled = {ZoneKeepaliveEnabled.Value} (default off since 1.2.86), radius "
                + $"{ZoneKeepaliveRadius.Value} zone(s), {ZoneKeepaliveSeconds.Value:0} s after leaving");

            if (PluginEnabled.Value)
            {
                ApplyPatches();
                // 1.2.210 ([generator] port of Core's Far\, integrated by [ghost]): EBM owns the far view now. Order as Core's owners called it;
                // FarCache creates FarRunner (and so the far job drain) here; ImpostorEngine hooks FarRunner lazily on its first kind / cell.
                try
                {
                    EasyBake.Far.FarRendering.Initialize(Config);   // 1.2.458 [visual] (Fire 11-18): [03 - Far Rendering] Far Rendering, the master switch (OFF), bound before every far renderer that reads it
                    EasyBake.Far.FarReach.Initialize(Config);   // 1.2.344 [ghost]: Far reach (one distance for every far system; [03 - Far Rendering] since 1.2.458), bound before the systems that read it
                    EasyBake.Far.FarZoneSet.Initialize(Config);   // 1.2.483 [visual] (Fire 11-21): [03 - Far Rendering] Far Zone Sync (ON under the OFF master), after Far reach, before the far layers
                    EasyBake.Far.FarFog.Initialize(Config);   // 1.2.346 [ghost]: [Far] Far fog scale
            EasyBake.Far.ImpostorEngine.Initialize(Config);
                    EasyBake.Far.FarVegRunner.Initialize(Config);   // 1.2.446 [visual]: EBM's own far tree placement ([03 - Far Rendering] Far Trees Own Placement, OFF)
                    EasyBake.Far.FarCache.Initialize(Config);
                    EasyBake.Far.FarLights.Initialize(Config);
                    EasyBake.Far.FarBuildings.Initialize(Config);
                    EasyBake.Far.FarTerrainTiles.Initialize(Config);   // 1.2.419 [visual]: EBM far ground ([03 - Far Rendering] Far Terrain, OFF until Fire passes it)
                    EasyBake.Far.FarRocks.Initialize(Config);   // 1.2.340 [visual]: far rocks (G3 of the far-drawing plan), OFF until the shore-pose gate
                }
                catch (System.Exception ex) { EasyBakeLog.Error($"[Far] far view init failed: {ex.Message}"); }
            }
            else
                EasyBakeLog.Info(
                    $"{PluginName} v{PluginVersion} loaded but PluginEnabled=false Ã¢â‚¬â€ no patches applied. " +
                    "Flip PluginEnabled to true in the config manager to enable live (no restart needed).");

            EasyBake.IdleGates.Bind(Config);
            EasyBake.EbmParticleIdle.Bind(Config);   // [seasons] 11-09 E34 (off)
            EasyBake.EbmBakeMemRelease.Bind(Config);   // [seasons] 11-09 E25 (off)
            EasyBake.GpuReleaseFence.Bind(Config);     // [seasons] 11-09 E23 (off)
            EasyBake.EbmHandoffCensus.Bind(Config);   // [seasons] 11-09 E28 census (off)
            EasyBake.EbmShaderWarm.Bind(Config);      // [seasons] 11-09 E30 (off)
            EasyBake.SnowFeed.Bind(Config);           // 1.2.259 [Snow] SnowRefreshPoll (ON, a fix)
            EasyBake.EbmSnowStore.Bind(Config);       // 1.2.260 [Snow] WaitForPushedSnow (ON, a fix)
            EasyBake.PieceCaps.Bind(Config);          // 1.2.505 [08 - Snow And Seasons] Draw Snow Caps On Baked Pieces (default OFF)
            EasyBake.SkipEligibility.BindSnowLayer(Config);   // 1.2.502 [08 - Snow And Seasons] Baked Pieces Under Snow Layer (default OFF)
            EasyBake.Indirect.EbmRenderCensus.Bind(Config);   // [seasons] 11-09 E39 (off; or -ebmrendercensus)
            EasyBake.Indirect.EbmIndirect.BindSkyDepth(Config);   // [seasons] 11-09 E31 (pass + throttle keys, off; census always at Debug)
            EasyBake.Indirect.EbmIndirect.BindDepthCull(Config);   // [seasons] 11-11 E2: depth-pyramid occlusion cull (ON to test), near band, Verify
            EasyBake.WaterTightBounds.Bind(Config);   // [seasons] 11-11 A3: water tile boxes = their wave slab; OFF until gate ABBA
            EasyBake.Indirect.EbmIndirect.BindWaterOccl(Config);   // 1.2.305 A2: water tiles behind hills / buildings not drawn (E2 pyramid, built for A2 alone if needed); OFF until gate
            EasyBake.WaterHideBuried.Bind(Config);   // [seasons] 11-11 A1: buried water tiles not drawn (Tools\PLAN_ebm_water_tile_cull_20261111.md); OFF until gate ABBA
            EasyBake.WaterSplit.Bind(Config);   // [seasons] 11-11 W2: lit water tiles drawn as 16 pieces (Tools\PLAN_ebm_water_draws_20261111.md)
            EasyBake.GpuFires.Bind(Config);   // [seasons] 11-11: torches / fires beyond the near band share phase templates, drawn instanced (ON to test)
            EasyBake.StandItemCull.Bind(Config);   // 1.2.300: hung-item distance cull + shadow cut (both OFF until gate ABBA)
            EasyBake.SignTextCull.Bind(Config);   // 1.2.295-ghost: sign writing farther than SignTextDrawM is not drawn (ON to test) + Verify (off)
            EasyBake.EbmTerrainShader.Bind(Config);
            EasyBake.EbmChurn.Bind(Config); EasyBake.EbmChurn.BindWinterKeep(Config); EasyBake.EbmChurn.BindLevers481(Config);   // 1.2.481: F1 / F2 keys   // 1.2.480: [Churn] / [Settle] (ChurnLine, default off) + WinterKeepRadius (default 0)   // 1.2.313 ([ghost]): EBM's own terrain shader on non-snow chunks (OFF until gate ABBA) + Verify (off); FTS stands down via EbmApi.HandlesShader
            EasyBake.EbmMist.Bind(Config);   // 1.2.388 [visual]: EBM's own mist shader on the Lux mist materials (MistShader, ON) + MistParticleCount / MistOpacity (1 = vanilla); FTS stands down via EbmApi.HandlesShader
            EasyBake.EbmWater.Bind(Config);   // 1.2.314 [seasons]: EBM's own water shader (EBM/Water, a copy of FTS FiresWater) on zone water (OFF until gate) + Verify (off); FTS stands down via EbmApi.HandlesShader
            EasyBakeLog.Info("[Indirect] indirect draws: camera motion vectors (12 RenderParams sites + the 2 impostor draws moved to RenderMeshIndirect; 1.2.350: RenderParams defaulted to Object and Unity re-drew our indirect batches in its per-object motion-vector pass with Hidden/Internal-MotionVectors, which knows nothing of the instance buffer: [ghost]'s capture 010313 frame 2086 = Fire's teal TAA wash)");
            EasyBake.InvulnerableClassifier.FollowSeasons();   // 1.2.176
            LightFlickerViewCull = EbmConfigMove.Bind(Config, "21 - Performance - Lights, Fires And Sound", "LightFlickerViewCull", true, "A light whose whole range is outside the camera flickers at LightFlickerDistantRate. It needs LightFlickerLodEnabled. Off = distance tiers only.");
            LightSettingsEvent = EbmConfigMove.Bind(Config, "21 - Performance - Lights, Fires And Sound", "LightSettingsEvent", true, "Lights share one graphics-settings hook instead of one subscription each, so unloading many lights costs less. Off = vanilla.");
            MinimapFogPartialUpload = EbmConfigMove.Bind(Config, "23 - Performance - World Objects", "MinimapFogPartialUpload", true, "Newly explored map pixels upload as a small rectangle instead of the whole fog texture. Off = vanilla.");
            EbmConfigMove.End(Config);   // 1.2.444: after the LAST bind of startup (the old SayMovedKeys point, moved below the last three binds): one log line, the cfg written once
            CoreLink.SayIfAbsent();
            try { Utilities.EbmHelpContent.Register(); }
            catch (System.Exception ex) { EasyBakeLog.Warn($"Help registration failed: {ex.Message}"); }

            CoreLink.RegisterStatus(StatusSource, DescribeStatus);

            // Compact "loaded" banner Ã¢â‚¬â€ oven with heat squiggles. Deferred to
            // world-load time (when ZNetScene is up) so it bookends the load;
            // the BIG "loading" banner already fired at the top of Awake.
            StartCoroutine(EmitCompactBannerWhenZNetReady());
        }


        // EBM's line in Core's status box: idle CreateDestroyObjects ticks skipped, and create-budget passes held back.
        private static string DescribeStatus()
        {
            int skipped = Patches.ZNetScene_CreateDestroyObjects_Patch.TakeSkippedSinceStatus();
            string budget = Patches.ZNetScene_CreateObjectsSorted_Budget.TakeStatus();
            string gate = EasyBake.ScanGate.TakeStatus();
            budget = gate == null ? budget : (budget == null ? gate : gate + "; " + budget);
            string skips = skipped > 0 ? $"skipped {skipped:N0} idle CreateDestroyObjects ticks" : null;
            if (skips == null) return budget;
            return budget == null ? skips : $"{skips}; {budget}";
        }

        // Waits for ZNetScene + its prefab table to be live (same readiness
        // signal the other Fires mods use), then emits the compact loaded
        // banner. Failure is non-fatal Ã¢â‚¬â€ falls back to a plain "loaded" log
        // line so the load event is still recorded in the file log.
        private IEnumerator EmitCompactBannerWhenZNetReady()
        {
            while (ZNetScene.instance == null
                   || ZNetScene.instance.m_prefabs == null
                   || ZNetScene.instance.m_prefabs.Count == 0)
            {
                yield return null;
            }
            yield return new WaitForEndOfFrame();

            try { FiresEasyBakeBanner.Print(); }
            catch (System.Exception ex)
            {
                EasyBakeLog.Info($"{PluginName} v{PluginVersion} loaded. (banner failed: {ex.Message})");
            }
        }

        // Idempotent. Walks every [HarmonyPatch] class in this assembly and
        // patches it, logging per-patch failures so a single bad target
        // doesn't take down the whole set. Sets _patchesApplied = true on
        // first run; subsequent calls are no-ops.
        private void ApplyPatches()
        {
            if (_patchesApplied) return;

            // 1.2.212 ([ghost], F2): a type list that cannot throw, the innermost reason, and a roll-back of a class that failed half-way (EbmPatchSafety)
            int succeeded = 0, failed = 0, methods = 0;
            var failedNames = new System.Collections.Generic.List<string>();
            foreach (var type in EasyBake.EbmPatchSafety.PatchTypes(typeof(FiresEasyBakeMeshesPlugin).Assembly))
            {
                if (type == null || type.GetCustomAttributes(typeof(HarmonyPatch), false).Length == 0) continue;
                try
                {
                    var patched = _harmony.CreateClassProcessor(type).Patch();
                    if (patched != null) methods += patched.Count;
                    succeeded++;
                }
                catch (System.Exception ex)
                {
                    failed++;
                    failedNames.Add(type.Name);
                    int undone = EasyBake.EbmPatchSafety.RollBack(_harmony, type);
                    var cause = EasyBake.EbmPatchSafety.Innermost(ex);
                    EasyBakeLog.Error($"Patch {type.Name} failed ({cause.GetType().Name}: {cause.Message}); that part of EBM is off this session, the rest works"
                        + (undone > 0 ? $"; {undone} part(s) it had already applied were removed again, so it never runs half-way" : ""));
                }
            }
            _patchesApplied = true;
            EasyBakeLog.Info(
                $"{PluginName} v{PluginVersion} active Ã¢â‚¬â€ {succeeded} patches registered ({methods} game methods), {failed} skipped{(failed > 0 ? ": " + string.Join(", ", failedNames) : "")}. " +
                $"Batching={(BatchingEnabled.Value ? "on" : "off")}, Prewarm={(PrewarmEnabled.Value ? "on" : "off")}.");
        }

        // Removes every patch this Harmony instance applied (won't touch
        // patches owned by other mods), then resets every EasyBake subsystem
        // that holds state so a re-enable later starts clean. ZoneTracker.Reset
        // is the cascade Ã¢â‚¬â€ it tears down all baked zones (calling
        // MeshBaker.Restore per zone to flip MeshRenderers back on) and
        // internally invokes Reset on InvulnerableClassifier, ZoneKeepalive,
        // DestroyTimeSlicer, SectorInstanceMirror, and StaticPieceZSyncSkip.
        // The two patch classes that carry per-frame skip-cache state
        // (CreateDestroyObjectsPatches, ClutterSystemPatches) need their own
        // ResetState calls Ã¢â‚¬â€ they're not subsystems ZoneTracker knows about.
        private static float s_disablingSince = -1f;   // 1.2.351: >= 0 while the master switch is off but the hand-back has not landed
        internal static bool Disabling => s_disablingSince >= 0f;
        private void FinishDisableIfLanded()
        {
            if (s_disablingSince < 0f) return;
            float waited = Time.unscaledTime - s_disablingSince;
            bool landed = EasyBake.ZoneTracker.HandBacksLandedAndHoldsExpired();
            if (!landed && waited < 60f) return;
            s_disablingSince = -1f;
            RemovePatches();
            EasyBakeLog.Info($"{PluginName} disable finished after {waited:0.0} s: {(landed ? "every handed-back piece exists and the support holds expired" : "60 s cap reached, remaining stand-ins released")}; patches removed, subsystem state reset.");
        }

        private void RemovePatches()
        {
            if (!_patchesApplied) return;
            try { _harmony?.UnpatchSelf(); }
            catch (System.Exception ex) { EasyBakeLog.Error($"UnpatchSelf failed: {ex.Message}"); }

            try { EasyBake.ZoneTracker.Reset(); } catch { }
            try { EasyBake.DamageReplay.Reset(); } catch { }
            try { Patches.ZNetScene_CreateDestroyObjects_Patch.ResetState(); } catch { }
            try { Patches.ClutterSystem_LateUpdate_Patch.ResetState(); } catch { }

            _patchesApplied = false;
        }

        // Tear down on plugin unload so the host process doesn't leave our
        // patches dangling against assembly_valheim. UnpatchSelf is a no-op
        // when _patchesApplied is false.
        // 1.2.97 ([fgn] 10-13): at game quit the process is ending, and UnpatchSelf made Harmony rebuild every method EBM patched and
        // re-run every other mod's patches on them during logout. Unpatch only for a real hot-unload, never once Application.quitting fired.
        private static bool s_quitting;
        private void OnDestroy() { EasyBake.Indirect.EbmIndirect.Shutdown(); if (!s_quitting) RemovePatches(); EasyBakeLog.StopAsync(); }   // AsyncLog: the queue is written before the plugin goes

        private bool _ticksHandedBack;

        private void Update()
        {
            long tSelf = EasyBake.EbmSelfCost.T();   // 1.2.219: EBM's own per-frame cost
            try { UpdateInner(); } finally { EasyBake.EbmSelfCost.Acc(0, tSelf); }
        }

        private void UpdateInner()
        {
            // 1.2.367 ([seasons], [lead] GC row "FiresEasyBakeMeshesPlugin.Update() > GC.Alloc" 2.17 KB/frame): each tick below in its own profiler scope
            // (EasyBake.UpdateMarkers), so a capture names the tick that allocates. Markers only: same calls, same order, same EbmSelfCost timers.
            long u7 = EasyBake.EbmSelfCost.UT(); using (EasyBake.UpdateMarkers.Heartbeat.Auto()) EasyBake.EbmTrace.Heartbeat(); EasyBake.EbmSelfCost.U(7, u7);   // 1.2.96; 1.2.224 timed
            // 1.2.169: these ran with the master switch off, which removes only the Harmony patches; 1.2.351: the tick also runs while DISABLING (hand-back landing)
            if (PluginEnabled.Value || Disabling)
            {
                _ticksHandedBack = false;
                long u0 = EasyBake.EbmSelfCost.UT();
                using (EasyBake.UpdateMarkers.RemoteItem.Auto()) EasyBake.RemoteItemZSyncSkip.Tick();
                using (EasyBake.UpdateMarkers.ShelterProbe.Auto()) EasyBake.ShelterProbe.Tick();   // 1.2.126
                using (EasyBake.UpdateMarkers.ShelterRain.Auto()) ShelterRain.Tick();   // 1.2.128
                using (EasyBake.UpdateMarkers.WetOverride.Auto()) EasyBake.WetOverride.Tick();   // 1.2.131
                using (EasyBake.UpdateMarkers.LightBudget.Auto()) EasyBake.LightBudget.Tick();   // 1.2.136
                EasyBake.EbmSelfCost.U(0, u0); u0 = EasyBake.EbmSelfCost.UT();
                using (EasyBake.UpdateMarkers.FillTracker.Auto()) EasyBake.FillTracker.Tick(); EasyBake.EbmSelfCost.U(1, u0); u0 = EasyBake.EbmSelfCost.UT();   using (EasyBake.UpdateMarkers.CoverageReach.Auto()) EasyBake.Indirect.Coverage.CoverageReach.Tick(); EasyBake.EbmSelfCost.U(5, u0); u0 = EasyBake.EbmSelfCost.UT();   using (EasyBake.UpdateMarkers.Censuses.Auto()) { EasyBake.Indirect.CasterCensus.Tick(); EasyBake.Indirect.PhysicsCensus.Tick(); EasyBake.Indirect.EbmLodLevelCensus.Tick(); EasyBake.EbmHeapCensus.Tick(); }   EasyBake.EbmSelfCost.U(6, u0);   /* 1.2.225: + [ghost] physics census */   /* 1.2.223: three timers */   // 1.2.216 ([ghost]): Debug-only 30 s census of vanilla shadow casters   // 1.2.214 ([ghost] P2 + P1 census): one compare a frame unless the camera moved 8 m
            }
            else
            {
                if (!_ticksHandedBack)
                {
                    _ticksHandedBack = true;
                    EasyBake.RemoteItemZSyncSkip.Reset();
                    ShelterRain.HandBack();
                    EasyBake.LightBudget.RestoreAll();
                    EasyBakeLog.Debug("[EBM] PluginEnabled off: rain hider, wet override, shelter probe, light budget and item skip stopped, their changes handed back");
                }
                using (EasyBake.UpdateMarkers.WhileOff.Auto()) EasyBake.WetOverride.FollowWhileOff();   // 1.2.367: marker only
            }
            // Kick the disk-cache background preload as soon as the world UID
            // is available. ZNet.GetWorldUID returns 0 until the server world
            // handshake completes; once it's non-zero, the cache directory
            // for this world is well-defined and we can start reading. The
            // worker runs on a ThreadPool task; touching only file I/O + POCO
            // arrays, no Unity API. By the time pieces start streaming in for
            // any zone, most or all of its cache file is already parsed into
            // memory, so the per-zone hit cost is just Mesh.SetVertices.
            //
            // KickPreload is idempotent and cheap when already kicked, so
            // calling it every Update before the first non-zero UID is fine.
            //
            // Route through MeshCacheStore.TryGetWorldUid() Ã¢â‚¬â€ it pre-checks
            // ZNet.m_world via reflection. Vanilla GetWorldUID() does an
            // unchecked dereference of m_world and NREs every frame in the
            // ~6s window between ZNet.instance being assigned and the world
            // handshake landing.
            // 1.2.156 ([visual], Fire 10-31 event-driven rule): once the preload is kicked for this ZNet, the per-frame reflection read
            // of m_world stops; a new ZNet (the next world) arms it again. KickPreload was already a no-op on every later frame.
            long u8 = EasyBake.EbmSelfCost.UT();   // 1.2.224: the preload kick (reflection read until kicked)
            using (EasyBake.UpdateMarkers.PreloadKick.Auto())   // 1.2.367: marker only
            if (CachePersistEnabled.Value && !ReferenceEquals(ZNet.instance, s_preloadKickedFor))
            {
                long uid = EasyBake.MeshCacheStore.TryGetWorldUid();
                if (uid != 0L)
                {
                    EasyBake.MeshCacheStore.KickPreload(uid);
                    if (EasyBake.MeshCacheStore.PreloadKickedFor(uid)) s_preloadKickedFor = ZNet.instance;
                    if (s_preloadKickedFor != null) EasyBakeLog.Debug($"[Cache] world id {uid:x16} seen: preload kicked, the per-frame world-id check stops until the next world");
                }
            }

            // Debounced ZONES BAKED mini-box: emits once ~5s after the last
            // cache-construct / fresh-bake event. Runs before the batching
            // gate so the final box still lands if batching is toggled off
            // right after login.
            EasyBake.EbmSelfCost.U(8, u8);
            long u2 = EasyBake.EbmSelfCost.UT();
            using (EasyBake.UpdateMarkers.BakeSummary.Auto()) BakeSummary.Update();   // 1.2.367: marker only

            // Drains ABOVE the batching gate on purpose. A hit caught for an uncreated piece must still be
            // replayed or reported lost even if batching is switched off in the same breath - inside the gate,
            // toggling the config off mid-flight would leave the queue frozen and the damage silently gone,
            // which is the one outcome this whole path exists to prevent. Costs one int compare when empty.
            using (EasyBake.UpdateMarkers.DamageReplay.Auto()) EasyBake.DamageReplay.Update();   // 1.2.367: marker only
            EasyBake.EbmSelfCost.U(2, u2);

            if (!BatchingActive())
            {
                // 1.2.357 ([visual], the 1351 switch-off arm 11-13 06:0x, results\fireclient-ebm1351-switchoff: "disabling via config: 13859 skipped piece(s) ... (60 s cap)"
                // and ~90 s later "re-enabled via config before the disable finished: patches were never removed"; the 13 landings came only after the re-enable,
                // all "at the cap"): the hand-back landings (ZoneTracker.Update -> FinishHandBacks) and the cap check sat BELOW this gate, and BatchingActive() is
                // false the moment PluginEnabled is false, so while DISABLING nothing landed and the 60 s cap never fired. Now the landing, the 30 s [Transition]
                // line and the finish check tick here while disabling; nothing else of the tracker runs (no bake, no skip, no conversion).
                if (Disabling) { EasyBake.ZoneTracker.TickDisabling(Time.unscaledTime); FinishDisableIfLanded(); }
                return;
            }
            long tZone = EasyBake.Probe.Start();
            long trackStart = System.Diagnostics.Stopwatch.GetTimestamp();
            long u3 = EasyBake.EbmSelfCost.UT();
            EasyBake.EbmSelfCost.ZtBegin(); using (EasyBake.UpdateMarkers.ZoneTracker.Auto()) EasyBake.ZoneTracker.Update(); EasyBake.EbmSelfCost.ZtEnd(u3); if (Disabling) FinishDisableIfLanded();   // 1.2.367: marker on ZoneTracker.Update only;   // 1.2.351   // 1.2.224: the worst frame keeps its phase split
            EasyBake.EbmSelfCost.U(3, u3);
            EasyBake.InstancedDraw.NoteZoneTracking(System.Diagnostics.Stopwatch.GetTimestamp() - trackStart);
            EasyBake.Probe.Stop("EasyBake:zoneTrack", tZone);

            // Keepalive lifecycle: refresh entries within the active ring,
            // prune entries that have drifted past KeepaliveRadius or aged
            // out. The RemoveObjects prefix consults the resulting set every
            // CreateDestroyObjects tick.
            // 1.2.122: keep-alive keys are x,z deltas; on the ring (object sectors ring-keyed) it stands down
            if (ZoneKeepaliveEnabled.Value && !EasyBake.EbmZones.Ring
                && ZNet.instance != null
                && ZoneSystem.instance != null
                && Player.m_localPlayer != null)
            {
                var refPos = ZNet.instance.GetReferencePosition();
                var center = ZoneSystem.GetZone(refPos);
                // Valheim 1.0: the fixed m_activeArea radius became the player-configurable,
                    // server-synced SimulationDistance.
                    int activeArea = ZNet.instance.GetSyncedSimulationDistance().NearSimulationDistance;
                long tKeep = EasyBake.Probe.Start();
                long u4 = EasyBake.EbmSelfCost.UT();
            using (EasyBake.UpdateMarkers.Keepalive.Auto()) EasyBake.ZoneKeepalive.Update(center, activeArea);   // 1.2.367: marker only
            EasyBake.EbmSelfCost.U(4, u4);
                EasyBake.Probe.Stop("EasyBake:keepalive", tKeep);
            }

            // Sector mirror periodic rebuild Ã¢â‚¬â€ corrects drift from instances
            // that moved sectors since they were instantiated. Cheap when
            // disabled (SectorMirrorRebuildSeconds=0) or interval not yet
            // elapsed; expensive (~1 walk of m_instances) when it actually
            // rebuilds.
            long u9 = EasyBake.EbmSelfCost.UT();   // 1.2.224
            if (SectorMirrorEnabled.Value && ZNetScene.instance != null)
            {
                long tMirror = EasyBake.Probe.Start();
                using (EasyBake.UpdateMarkers.SectorMirror.Auto()) EasyBake.SectorInstanceMirror.MaybeRebuild(ZNetScene.instance);   // 1.2.367: marker only
                EasyBake.Probe.Stop("EasyBake:sectorMirror", tMirror);
            }

            // Static-piece ZSync skip: periodic verbose summary if enabled.
            // No-op when ZSyncStaticSkipVerbose=false. Cheap enough to call
            // every Update Ã¢â‚¬â€ guards on the throttle internally.
            using (EasyBake.UpdateMarkers.ZSyncReport.Auto()) EasyBake.StaticPieceZSyncSkip.MaybeReport();   // 1.2.367: marker only
            EasyBake.EbmSelfCost.U(9, u9);
        }

        // Instances are drawn here rather than in Update because GameCamera moves the
        // camera in its own LateUpdate: deciding what is out of view any earlier would
        // test last frame's view and let a fast turn clip geometry at the screen edge.
        private void LateUpdate()
        {
            long tSelf = EasyBake.EbmSelfCost.T();   // 1.2.219: EBM's own per-frame cost
            try { LateUpdateInner(); } finally { EasyBake.EbmSelfCost.Acc(1, tSelf); }
        }

        // 1.2.326 ([lead] / Fire: "optimize ebms late updates"; the census: EBM's LateUpdate 0.756 ms/frame at the settled town): every call below is
        // timed in its own slot (two Stopwatch reads a call, ~1 us a frame for all of them) and one Info line every 30 s ranks them, so a settled leg
        // names the top parts before anything is optimized (Fire: only where the SAME function costs less). DrawInstances keeps its own finer split
        // (InstancedDraw sub-timers: dead check / Take / legacy submit) in its existing lines.
        private static readonly string[] s_luNames = {
            "LightCensus", "SkipCensus", "WaterHideBuried", "WaterTightBounds", "WaterOccl", "WaterSplit", "GpuFires", "StreamPacerWatch",
            "CacheSummary", "StandItemCull", "SignTextCull", "TerrainShader", "WaterShader", "ShaderOwnership", "FarTick", "StaticClusters",
            "CoverageRegistry", "CoveredFlush", "DrawInstances" };
        private static readonly long[] s_luTicks = new long[19];
        private static long s_luFrames; private static float s_luReportAt;
        private static long s_luT;
        // 1.2.355 ([lead]: dock-stand-3 capture frame 1495 = Plugin.LateUpdate 53.7 ms self, unnamed): per-frame slot ticks are kept for the last frame; at the
        // next frame's start the finished frame is compared with the window's worst and the worst frame's top slot is remembered for the 30 s line.
        private static readonly long[] s_luFrameTicks = new long[19];
        private static long s_luWorstFrameTicks; private static int s_luWorstSlot = -1; private static long s_luWorstSlotTicks;
        // 1.2.356 ([2ic], lead 11-13 profiler: Plugin.LateUpdate 3.0 MB/min, 41k allocations of ~76 B, all on the one LateUpdate line because the 19 ticks
        // inline into it): each slot's managed heap growth (Mono used size before / after; a GC in between reads negative and is dropped), Debug only,
        // so the 30 s [SelfCost] LateUpdate line names which tick allocates. One GetMonoUsedSizeLong per slot while Debug is on; nothing when off.
        private static readonly long[] s_luAlloc = new long[19];
        private static long s_luMono; private static bool s_luAllocOn; private static float s_luAllocSince;
        private static void LuMono() { if (s_luAllocOn) s_luMono = UnityEngine.Profiling.Profiler.GetMonoUsedSizeLong(); }
        private static void LuMark(int slot)
        {
            long n = System.Diagnostics.Stopwatch.GetTimestamp(); s_luTicks[slot] += n - s_luT; s_luFrameTicks[slot] += n - s_luT; s_luT = n;
            if (s_luAllocOn) { long mm = UnityEngine.Profiling.Profiler.GetMonoUsedSizeLong(); long d = mm - s_luMono; if (d > 0) s_luAlloc[slot] += d; s_luMono = mm; }
        }
        private static void LuCloseFrame()
        {
            long tot = 0; int top = -1; long topT = -1;
            for (int i = 0; i < s_luFrameTicks.Length; i++) { tot += s_luFrameTicks[i]; if (s_luFrameTicks[i] > topT) { topT = s_luFrameTicks[i]; top = i; } s_luFrameTicks[i] = 0; }
            if (tot > s_luWorstFrameTicks) { s_luWorstFrameTicks = tot; s_luWorstSlot = top; s_luWorstSlotTicks = topT; }
        }
        private static void LuReport()
        {
            float now = Time.unscaledTime;
            if (now < s_luReportAt) return;
            bool first = s_luReportAt == 0f;
            s_luReportAt = now + 30f;
            if (first || s_luFrames == 0) { System.Array.Clear(s_luTicks, 0, s_luTicks.Length); System.Array.Clear(s_luAlloc, 0, s_luAlloc.Length); s_luAllocSince = now; s_luFrames = 0; System.Array.Clear(EasyBake.ZoneTracker.DwSeg, 0, 5); EasyBake.ZoneTracker.DwSettled = 0; return; }
            // 1.2.327 ([lead]: 1.2.326 printed raw ticks): ms per frame = ticks * 1000 / Frequency / frames
            double f = 1000.0 / System.Diagnostics.Stopwatch.Frequency / s_luFrames, total = 0;
            var idx = new int[s_luTicks.Length]; for (int i = 0; i < idx.Length; i++) { idx[i] = i; total += s_luTicks[i] * f; }
            System.Array.Sort(idx, (a, b) => s_luTicks[b].CompareTo(s_luTicks[a]));
            var sb = new System.Text.StringBuilder($"[SelfCost] LateUpdate last 30 s ({s_luFrames} frames): {total:0.000} ms/frame; ");
            for (int k = 0; k < idx.Length; k++) { double ms = s_luTicks[idx[k]] * f; if (k >= 8 && ms < 0.005) break; sb.Append(s_luNames[idx[k]]).Append(' ').Append(ms.ToString("0.000")).Append(k + 1 < idx.Length ? ", " : ""); }
            // 1.2.327: DrawInstances' coarse split (ZoneTracker.DwSeg), the same frames
            var dw = EasyBake.ZoneTracker.DwSeg;
            sb.Append($"; DrawInstances split: begin {dw[0] * f:0.000}, settled walk {dw[1] * f:0.000}, full zone walk {dw[2] * f:0.000}, indirect EndFrame (cull + draw) {dw[3] * f:0.000}, rest {dw[4] * f:0.000}; settled frames {EasyBake.ZoneTracker.DwSettled * 100.0 / s_luFrames:0}%");
            double wf = s_luWorstFrameTicks * 1000.0 / System.Diagnostics.Stopwatch.Frequency, ws = s_luWorstSlotTicks * 1000.0 / System.Diagnostics.Stopwatch.Frequency;
            sb.Append($"; worst frame {wf:0.0} ms (top slot {(s_luWorstSlot >= 0 ? s_luNames[s_luWorstSlot] : "-")} {ws:0.0} ms)");   // 1.2.355
            s_luWorstFrameTicks = 0; s_luWorstSlot = -1; s_luWorstSlotTicks = 0;
            // 1.2.356: heap growth per slot (Debug only), the top 5 in MB/min
            if (s_luAllocOn)
            {
                float mins = Mathf.Max(1f, now - s_luAllocSince) / 60f; long allocTot = 0;
                for (int i = 0; i < idx.Length; i++) { idx[i] = i; allocTot += s_luAlloc[i]; }
                System.Array.Sort(idx, (a, b) => s_luAlloc[b].CompareTo(s_luAlloc[a]));
                sb.Append($"; heap growth {allocTot / 1048576f / mins:0.00} MB/min (approx., process-wide while each slot ran):");
                for (int k = 0; k < 5 && k < idx.Length; k++) { if (s_luAlloc[idx[k]] <= 0) break; sb.Append(' ').Append(s_luNames[idx[k]]).Append(' ').Append((s_luAlloc[idx[k]] / 1048576f / mins).ToString("0.00")).Append(','); }
            }
            System.Array.Clear(s_luAlloc, 0, s_luAlloc.Length); s_luAllocSince = now;
            if (total > 1000.0) EasyBakeLog.Warn($"[SelfCost] LateUpdate total {total:0} ms/frame is impossible: the timer is wrong, line not trusted ({s_luFrames} frames)");
            else EasyBakeLog.InfoFirst("SelfCost LateUpdate 30 s", sb.ToString().TrimEnd(',', ' '));   // 1.2.364: first Info, then Debug (repeating)
            System.Array.Clear(s_luTicks, 0, s_luTicks.Length); s_luFrames = 0;
            System.Array.Clear(dw, 0, dw.Length); EasyBake.ZoneTracker.DwSettled = 0;
        }

        private void LateUpdateInner()
        {
            EasyBake.EbmTrace.HitchFrameTick();   // 1.2.491 (A): [Hitch-EBM] the previous frame's EBM handoff counts, when it took 50 ms or more (Debug only)
            EasyBake.InvulnerableClassifier.CensusTick();   // 1.2.492: [WearSkip] census every 30 s (Debug only, read-only)
            LuCloseFrame();   // 1.2.355: the previous frame's slots -> worst-frame record
            s_luFrames++; s_luT = System.Diagnostics.Stopwatch.GetTimestamp();
            s_luAllocOn = EasyBakeLog.DebugOn(); LuMono();   // 1.2.356: per-slot heap growth only while Debug is on
            // 1.2.362 ([lead]: "EBM LateUpdate self 117 ms once, frame 1181, nothing of its children named" in O_20261114_003628): every call below in its own profiler scope
            // (the names of the [SelfCost] LateUpdate slots), so a non-deep capture names the part. Markers only; the slot timing (LuMark) is unchanged.
            var lu = EasyBake.EbmPatchMarkers.Lu;
            using (lu[0].Auto()) EasyBake.EbmLightCensus.Tick(); LuMark(0);   // 1.2.275: hooks the tiny-light cut once, census every 30 s
            using (lu[1].Auto()) EasyBake.ZoneTracker.SkipCensusTick(); LuMark(1);   // 1.2.281: far-baked-piece census (Debug, 30 s)
            using (lu[2].Auto()) EasyBake.WaterHideBuried.Tick(); LuMark(2);
            using (lu[3].Auto()) EasyBake.WaterTightBounds.Tick(); LuMark(3);   // [seasons] 11-11 A3 (after A1: hidden tiles are skipped in its counts)   // [seasons] 11-11 A1 (before WaterSplit, so a hidden tile is never split)
            using (lu[4].Auto()) EasyBake.Indirect.EbmIndirect.WaterOcclTick(); LuMark(4);   // 1.2.305 A2 (after A1 / A3)
            using (lu[5].Auto()) EasyBake.WaterSplit.Tick(); LuMark(5);   // [seasons] 11-11 W2
            using (lu[6].Auto()) EasyBake.GpuFires.Tick(); LuMark(6);   // [seasons] 11-11: hooks the main camera's pre-cull draw once, census every 30 s
            using (lu[7].Auto()) EasyBake.StreamPacer.Watch(); LuMark(7);   // 1.2.315: says once if vanilla CreateObjects never runs (another mod creates its own way)
            using (lu[8].Auto()) EasyBake.MeshCacheStore.SummaryTick(); LuMark(8);   // 1.2.317: the [Cache] 30 s Info summary (counters only, only when something happened)
            using (lu[9].Auto()) EasyBake.StandItemCull.Tick(); LuMark(9);   // 1.2.300
            using (lu[10].Auto()) EasyBake.SignTextCull.Tick(); LuMark(10);   // 1.2.295-ghost: an eighth of the signs a frame (no signs = one compare)
            using (lu[11].Auto()) EasyBake.EbmTerrainShader.Tick(); LuMark(11);   // 1.2.313: one compare a frame, a chunk pass once a second
            using (lu[12].Auto()) { EasyBake.EbmWater.Tick(); EasyBake.EbmMist.Tick(); } LuMark(12);   // 1.2.314 [seasons]: one compare a frame (+ the depth-texture keep with no settings owner), a tile pass once a second
            using (lu[13].Auto()) EbmApi.RecheckShaderOwnership("1 s check", false); LuMark(13);   // 1.2.318 shader priority: one float compare a frame; the mask once a second (bundle / indirect state)
            using (lu[14].Auto()) EasyBake.ZoneTracker.FarTick(); LuMark(14);   // 1.2.284 SkipFarBakedPieces: hand-back on entering the active area (scans on an 8 m move)
            using (lu[15].Auto()) EasyBake.Indirect.Coverage.StaticClusters.Tick(); LuMark(15);   // 1.2.286: verify + census
            using (lu[16].Auto()) EasyBake.Indirect.Coverage.CoverageRegistry.Tick(); LuMark(16);   // 1.2.272 CoverageRegistryAttach: attach registered objects the camera can reach (idle = one compare)
            using (lu[17].Auto()) EasyBake.Indirect.Coverage.CoveredObject.FlushPending(); LuMark(17);   // CoverageBatchedStart: Unity runs this frame's Starts before the LateUpdate phase, so every spawn of ZNetScene.Update is queued by now
            using (lu[19].Auto()) EasyBake.ArrivalTimeline.Tick();   // 1.2.326 per-teleport [Arrival] timeline (one compare when no teleport)
#if EBM_BLACKFRAME   // 1.2.365 (Fire 11-14: commented out, re-enable to debug)
            using (lu[20].Auto()) EasyBake.EbmBlackFrameWatch.Tick();   // 1.2.359: before the batching gate, so the detector runs while EBM is switched off too
#endif
            if (!BatchingActive()) { using (lu[21].Auto()) LuReport(); return; }
            bool hot = EasyBake.EbmTrace.Hot;   // 1.2.96: trace the draw only right after destroys
            if (hot) EasyBake.EbmTrace.Step("draw instances begin", Time.frameCount);
            s_luT = System.Diagnostics.Stopwatch.GetTimestamp(); LuMono();   // 1.2.356: the arrival timeline above is not counted in DrawInstances' growth either
            using (lu[18].Auto()) EasyBake.ZoneTracker.DrawInstances(); LuMark(18);
            if (hot) EasyBake.EbmTrace.Step("draw instances end", Time.frameCount);
            using (lu[21].Auto()) LuReport();
        }

        public static bool BatchingActive()
        {
            if (!PluginEnabled.Value) return false;
            if (!BatchingEnabled.Value) return false;
            if (BatchingRunOnServer.Value) return true;
            return !(ZNet.instance != null && ZNet.instance.IsDedicated());
        }
    }
}
